    Long anotherDate = (long) Literal.of("1970-01-02T00:00:00.00000").to(TYPE).value();
    assertProjectionStrict(spec, notIn("timestamp", date, anotherDate), Expression.Operation.NOT_IN, "[1970-01-01, 1970-01-02]");
