    List<AppendFiles> pendingCommits = IntStream.range(0, nThreads).mapToObj(i -> table.newAppend().appendFile(dataFile)).collect(Collectors.toList());
    ExecutorService executorService = MoreExecutors.getExitingExecutorService((ThreadPoolExecutor) Executors.newFixedThreadPool(nThreads));
    Tasks.range(nThreads).retry(10000).throwFailureWhenFinished().executeWith(executorService).run(i -> pendingCommits.get(i).commit());
