@Test
public void testParallelCommitMultiThreadMultiCommit() {
    String namespace = createNamespace();
    String tableName = getRandomName();
    createTable(namespace, tableName);
    Table table = glueCatalog.loadTable(TableIdentifier.of(namespace, tableName));
    String fileName = UUID.randomUUID().toString();
    DataFile file = DataFiles.builder(table.spec()).withPath(FileFormat.PARQUET.addExtension(fileName)).withRecordCount(2).withFileSizeInBytes(0).build();
    ExecutorService executorService = MoreExecutors.getExitingExecutorService((ThreadPoolExecutor) Executors.newFixedThreadPool(2));
    AtomicInteger barrier = new AtomicInteger(0);
    Tasks.range(2).stopOnFailure().throwFailureWhenFinished().executeWith(executorService).run(index -> {
        for (int numCommittedFiles = 0; numCommittedFiles < 10; numCommittedFiles++) {
            while (barrier.get() < numCommittedFiles * 2) {
                try {
                    Thread.sleep(10);
                } catch (InterruptedException e) {
                    throw new RuntimeException(e);
                }
            }
            table.newFastAppend().appendFile(file).commit();
            barrier.incrementAndGet();
        }
    });
    table.refresh();
    Assert.assertEquals("Commits should all succeed sequentially", 20, table.history().size());
    Assert.assertEquals("should have 20 manifests", 20, table.currentSnapshot().allManifests().size());
}

