@Test
public void testListTables() {
    C catalog = catalog();
    Namespace ns1 = Namespace.of("ns_1");
    Namespace ns2 = Namespace.of("ns_2");
    TableIdentifier ns1Table1 = TableIdentifier.of(ns1, "table_1");
    TableIdentifier ns1Table2 = TableIdentifier.of(ns1, "table_2");
    TableIdentifier ns2Table1 = TableIdentifier.of(ns2, "table_1");
    if (requiresNamespaceCreate()) {
        catalog.createNamespace(ns1);
        catalog.createNamespace(ns2);
    }
    assertEmpty("Should not have tables in a new namespace, ns_1", catalog, ns1);
    assertEmpty("Should not have tables in a new namespace, ns_2", catalog, ns2);
    catalog.buildTable(ns1Table1, SCHEMA).create();
    Assert.assertEquals("Should contain ns_1.table_1 after create", ImmutableSet.of(ns1Table1), Sets.newHashSet(catalog.listTables(ns1)));
    catalog.buildTable(ns2Table1, SCHEMA).create();
    Assert.assertEquals("Should contain ns_2.table_1 after create", ImmutableSet.of(ns2Table1), Sets.newHashSet(catalog.listTables(ns2)));
    Assert.assertEquals("Should not show changes to ns_2 in ns_1", ImmutableSet.of(ns1Table1), Sets.newHashSet(catalog.listTables(ns1)));
    catalog.buildTable(ns1Table2, SCHEMA).create();
    Assert.assertEquals("Should not show changes to ns_1 in ns_2", ImmutableSet.of(ns2Table1), Sets.newHashSet(catalog.listTables(ns2)));
    Assert.assertEquals("Should contain ns_1.table_2 after create", ImmutableSet.of(ns1Table1, ns1Table2), Sets.newHashSet(catalog.listTables(ns1)));
    catalog.dropTable(ns1Table1);
    Assert.assertEquals("Should not show changes to ns_1 in ns_2", ImmutableSet.of(ns2Table1), Sets.newHashSet(catalog.listTables(ns2)));
    Assert.assertEquals("Should not contain ns_1.table_1 after drop", ImmutableSet.of(ns1Table2), Sets.newHashSet(catalog.listTables(ns1)));
    catalog.dropTable(ns1Table2);
    Assert.assertEquals("Should not show changes to ns_1 in ns_2", ImmutableSet.of(ns2Table1), Sets.newHashSet(catalog.listTables(ns2)));
    assertEmpty("Should not contain ns_1.table_2 after drop", catalog, ns1);
    catalog.dropTable(ns2Table1);
    assertEmpty("Should not contain ns_2.table_1 after drop", catalog, ns2);
}

