    ImmutableMap.of(1, longToBuffer(10L)))).build();
    DataFile secondDataFile = DataFiles.builder(spec).withPath("/path/to/data-1.parquet").withFileSizeInBytes(10).withPartitionPath("data_bucket=0").withMetrics(new Metrics(5L, // no column sizes
    null, // value count
    ImmutableMap.of(1, 5L, 2, 5L), // null count
    ImmutableMap.of(1, 0L, 2, 0L), // no nan value counts
    null, // lower bounds
    ImmutableMap.of(1, longToBuffer(0L)), // upper bounds
