    // add both data files
    table.newFastAppend().appendFile(firstDataFile).appendFile(secondDataFile).commit();
    Snapshot initialSnapshot = table.currentSnapshot();
    Assert.assertEquals("Should have 1 manifest", 1, initialSnapshot.allManifests().size());
    validateManifestEntries(initialSnapshot.allManifests().get(0), ids(initialSnapshot.snapshotId(), initialSnapshot.snapshotId()), files(firstDataFile, secondDataFile), statuses(Status.ADDED, Status.ADDED));
    // delete the first data file
    table.newDelete().deleteFile(firstDataFile).commit();
    Snapshot deleteSnapshot = table.currentSnapshot();
    Assert.assertEquals("Should have 1 manifest", 1, deleteSnapshot.allManifests().size());
    validateManifestEntries(deleteSnapshot.allManifests().get(0), ids(deleteSnapshot.snapshotId(), initialSnapshot.snapshotId()), files(firstDataFile, secondDataFile), statuses(Status.DELETED, Status.EXISTING));
    // delete the second data file using a row filter
    // the commit should succeed as there is only one live data file
