    Snapshot finalSnapshot = table.currentSnapshot();
    Assert.assertEquals("Should have 1 manifest", 1, finalSnapshot.allManifests().size());
    validateManifestEntries(finalSnapshot.allManifests().get(0), ids(finalSnapshot.snapshotId()), files(secondDataFile), statuses(Status.DELETED));
}

