@Test
public void testManifestsPartitionSummary() throws IOException {
    ByteBuffer firstSummaryLowerBound = Conversions.toByteBuffer(Types.IntegerType.get(), 10);
    ByteBuffer firstSummaryUpperBound = Conversions.toByteBuffer(Types.IntegerType.get(), 100);
    ByteBuffer secondSummaryLowerBound = Conversions.toByteBuffer(Types.IntegerType.get(), 20);
    ByteBuffer secondSummaryUpperBound = Conversions.toByteBuffer(Types.IntegerType.get(), 200);
    List<ManifestFile.PartitionFieldSummary> partitionFieldSummaries = Lists.newArrayList(new GenericPartitionFieldSummary(false, firstSummaryLowerBound, firstSummaryUpperBound), new GenericPartitionFieldSummary(true, false, secondSummaryLowerBound, secondSummaryUpperBound));
    ManifestFile manifest = new GenericManifestFile(PATH, LENGTH, SPEC_ID, ManifestContent.DATA, SEQ_NUM, MIN_SEQ_NUM, SNAPSHOT_ID, ADDED_FILES, ADDED_ROWS, EXISTING_FILES, EXISTING_ROWS, DELETED_FILES, DELETED_ROWS, partitionFieldSummaries, KEY_METADATA);
    InputFile manifestList = writeManifestList(manifest, 2);
    List<ManifestFile> files = ManifestLists.read(manifestList);
    ManifestFile returnedManifest = Iterables.getOnlyElement(files);
    Assert.assertEquals("Number of partition field summaries should match", 2, returnedManifest.partitions().size());
    ManifestFile.PartitionFieldSummary first = returnedManifest.partitions().get(0);
    Assert.assertFalse("First partition field summary should not contain null", first.containsNull());
    Assert.assertNull("First partition field summary has unknown NaN", first.containsNaN());
    Assert.assertEquals("Lower bound for first partition field summary should match", firstSummaryLowerBound, first.lowerBound());
    Assert.assertEquals("Upper bound for first partition field summary should match", firstSummaryUpperBound, first.upperBound());
