    V2Assert.assertEquals("Last sequence number should be 2", 2, base.lastSequenceNumber());
    V1Assert.assertEquals("Table should end with last-sequence-number 0", 0, base.lastSequenceNumber());
    Assert.assertEquals("Should contain 3 merged manifest for second write", 3, readMetadata().currentSnapshot().allManifests().size());
    validateManifest(snap2.allManifests().get(0), seqs(2), ids(commitId2), files(FILE_A), statuses(Status.ADDED));
    validateManifest(snap2.allManifests().get(1), seqs(2, 2), ids(commitId2, commitId2), files(FILE_C, FILE_D), statuses(Status.ADDED, Status.ADDED));
    validateManifest(snap2.allManifests().get(2), seqs(1, 1, 1), ids(commitId1, commitId1, commitId1), files(FILE_A, FILE_C, FILE_D), statuses(Status.EXISTING, Status.EXISTING, Status.EXISTING));
