@Test
public void testTruncateBinary() {
    ByteBuffer original = ByteBuffer.wrap(new byte[] { 1, 1, (byte) 0xFF, 2 });
    ByteBuffer emptyByteBuffer = ByteBuffer.allocate(0);
    Comparator<ByteBuffer> cmp = Literal.of(original).comparator();
    Assert.assertEquals("Truncating to a length of zero should return an empty ByteBuffer", 0, cmp.compare(truncateBinary(original, 0), emptyByteBuffer));
    Assert.assertEquals("Truncating to the original buffer's remaining size should return the original buffer", original, truncateBinary(original, original.remaining()));
    Assert.assertEquals("Truncating with a length greater than the input's remaining size should return the input", original, truncateBinary(original, 16));
    ByteBuffer truncated = truncateBinary(original, 2);
    Assert.assertTrue("Truncating with a length less than the input's remaining size should truncate properly", truncated.remaining() == 2 && truncated.position() == 0);
    Assert.assertTrue("Truncating should not modify the input buffer", original.remaining() == 4 && original.position() == 0);
    AssertHelpers.assertThrows("Should not allow a negative truncation length", IllegalArgumentException.class, "length should be non-negative", () -> truncateBinary(original, -1));
}

@Test
public void testTruncateBinaryMin() {
    ByteBuffer test1 = ByteBuffer.wrap(new byte[] { 1, 1, (byte) 0xFF, 2 });
    // Output of test1 when truncated to 2 bytes
    ByteBuffer test1_2_expected = ByteBuffer.wrap(new byte[] { 1, 1 });
    ByteBuffer test2 = ByteBuffer.wrap(new byte[] { (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, 2 });
    ByteBuffer test2_2 = ByteBuffer.wrap(new byte[] { (byte) 0xFF, (byte) 0xFF });
    Comparator<ByteBuffer> cmp = Literal.of(test1).comparator();
    Assert.assertTrue("Truncated lower bound should be lower than or equal to the actual lower bound", cmp.compare(truncateBinaryMin(Literal.of(test1), 2).value(), test1) <= 0);
    Assert.assertTrue("Output must have the first two bytes of the input", cmp.compare(truncateBinaryMin(Literal.of(test1), 2).value(), test1_2_expected) == 0);
    Assert.assertTrue("No truncation required as truncate length is greater than the input size", cmp.compare(truncateBinaryMin(Literal.of(test1), 5).value(), test1) == 0);
    Assert.assertTrue("Truncated lower bound should be lower than or equal to the actual lower bound", cmp.compare(truncateBinaryMin(Literal.of(test2), 2).value(), test2) <= 0);
    Assert.assertTrue("Output must have the first two bytes of the input. A lower bound exists " + "even though the first two bytes are the max value", cmp.compare(truncateBinaryMin(Literal.of(test2), 2).value(), test2_2) == 0);
}

@Test
public void testTruncateBinaryMax() {
    ByteBuffer test1 = ByteBuffer.wrap(new byte[] { 1, 1, 2 });
    ByteBuffer test2 = ByteBuffer.wrap(new byte[] { 1, 1, (byte) 0xFF, 2 });
    ByteBuffer test3 = ByteBuffer.wrap(new byte[] { (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, 2 });
    ByteBuffer test4 = ByteBuffer.wrap(new byte[] { 1, 1, 0 });
    ByteBuffer expectedOutput = ByteBuffer.wrap(new byte[] { 1, 2 });
    Comparator<ByteBuffer> cmp = Literal.of(test1).comparator();
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper bound", cmp.compare(truncateBinaryMax(Literal.of(test1), 2).value(), test1) >= 0);
    Assert.assertTrue("Output must have two bytes and the second byte of the input must be incremented", cmp.compare(truncateBinaryMax(Literal.of(test1), 2).value(), expectedOutput) == 0);
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper bound", cmp.compare(truncateBinaryMax(Literal.of(test2), 2).value(), test2) >= 0);
    Assert.assertTrue("Since the third byte is already the max value, output must have two bytes " + "with the second byte incremented ", cmp.compare(truncateBinaryMax(Literal.of(test2), 3).value(), expectedOutput) == 0);
    Assert.assertTrue("No truncation required as truncate length is greater than the input size", cmp.compare(truncateBinaryMax(Literal.of(test3), 5).value(), test3) == 0);
    Assert.assertNull("An upper bound doesn't exist since the first two bytes are the max value", truncateBinaryMax(Literal.of(test3), 2));
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper bound", cmp.compare(truncateBinaryMax(Literal.of(test4), 2).value(), test4) >= 0);
    Assert.assertTrue("Since a shorter sequence is considered smaller, output must have two bytes " + "and the second byte of the input must be incremented", cmp.compare(truncateBinaryMax(Literal.of(test4), 2).value(), expectedOutput) == 0);
}

@SuppressWarnings("checkstyle:AvoidEscapedUnicodeCharacters")
@Test
public void testTruncateStringMin() {
    String test1 = "イロハニホヘト";
    // Output of test1 when truncated to 2 unicode characters
    String test1_2_expected = "イロ";
    String test1_3_expected = "イロハ";
    String test2 = "щщаεはчωいにπάほхεろへσκζ";
    String test2_7_expected = "щщаεはчω";
    // U+FFFF is max 3 byte UTF-8 character
    String test3 = "\uFFFF\uFFFF";
    // test4 consists of 2 4 byte UTF-8 characters
    String test4 = "\uD800\uDC00\uD800\uDC00";
    String test4_1_expected = "\uD800\uDC00";
    Comparator<CharSequence> cmp = Literal.of(test1).comparator();
    Assert.assertTrue("Truncated lower bound should be lower than or equal to the actual lower bound", cmp.compare(truncateStringMin(Literal.of(test1), 3).value(), test1) <= 0);
    Assert.assertTrue("No truncation required as truncate length is greater than the input size", cmp.compare(truncateStringMin(Literal.of(test1), 8).value(), test1) == 0);
    Assert.assertTrue("Output must have the first two characters of the input", cmp.compare(truncateStringMin(Literal.of(test1), 2).value(), test1_2_expected) == 0);
    Assert.assertTrue("Output must have the first three characters of the input", cmp.compare(truncateStringMin(Literal.of(test1), 3).value(), test1_3_expected) == 0);
    Assert.assertTrue("Truncated lower bound should be lower than or equal to the actual lower bound", cmp.compare(truncateStringMin(Literal.of(test2), 16).value(), test2) <= 0);
    Assert.assertTrue("Output must have the first seven characters of the input", cmp.compare(truncateStringMin(Literal.of(test2), 7).value(), test2_7_expected) == 0);
    Assert.assertTrue("Truncated lower bound should be lower than or equal to the actual lower bound", cmp.compare(truncateStringMin(Literal.of(test3), 2).value(), test3) <= 0);
    Assert.assertTrue("No truncation required as truncate length is equal to the input size", cmp.compare(truncateStringMin(Literal.of(test3), 2).value(), test3) == 0);
    Assert.assertTrue("Truncated lower bound should be lower than or equal to the actual lower bound", cmp.compare(truncateStringMin(Literal.of(test4), 1).value(), test4) <= 0);
    Assert.assertTrue("Output must have the first 4 byte UTF-8 character of the input", cmp.compare(truncateStringMin(Literal.of(test4), 1).value(), test4_1_expected) == 0);
}

@SuppressWarnings("checkstyle:AvoidEscapedUnicodeCharacters")
@Test
public void testTruncateStringMax() {
    String test1 = "イロハニホヘト";
    // Output of test1 when truncated to 2 unicode characters
    String test1_2_expected = "イヮ";
    String test1_3_expected = "イロバ";
    String test2 = "щщаεはчωいにπάほхεろへσκζ";
    String test2_7_expected = "щщаεはчϊ";
    String test3 = "aनि\uFFFF\uFFFF";
    String test3_3_expected = "aनी";
    // U+FFFF is max 3 byte UTF-8 character
    String test4 = "\uFFFF\uFFFF";
    String test4_1_expected = "\uD800\uDC00";
    // test5 consists of 2 4 byte max UTF-8 characters
    String test5 = "\uDBFF\uDFFF\uDBFF\uDFFF";
    String test6 = "\uD800\uDFFF\uD800\uDFFF";
    // Increment the previous character
    String test6_2_expected = "\uD801\uDC00";
    String test7 = "\uD83D\uDE02\uD83D\uDE02\uD83D\uDE02";
    String test7_2_expected = "\uD83D\uDE02\uD83D\uDE03";
    String test7_1_expected = "\uD83D\uDE03";
    Comparator<CharSequence> cmp = Literal.of(test1).comparator();
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper bound", cmp.compare(truncateStringMax(Literal.of(test1), 4).value(), test1) >= 0);
    Assert.assertTrue("No truncation required as truncate length is equal to the input size", cmp.compare(truncateStringMax(Literal.of(test1), 7).value(), test1) == 0);
    Assert.assertTrue("Output must have two characters and the second character of the input must " + "be incremented", cmp.compare(truncateStringMax(Literal.of(test1), 2).value(), test1_2_expected) == 0);
    Assert.assertTrue("Output must have three characters and the third character of the input must " + "be incremented", cmp.compare(truncateStringMax(Literal.of(test1), 3).value(), test1_3_expected) == 0);
    Assert.assertTrue("No truncation required as truncate length is greater than the input size", cmp.compare(truncateStringMax(Literal.of(test1), 8).value(), test1) == 0);
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper " + "bound", cmp.compare(truncateStringMax(Literal.of(test2), 8).value(), test2) >= 0);
    Assert.assertTrue("Output must have seven characters and the seventh character of the input " + "must be incremented", cmp.compare(truncateStringMax(Literal.of(test2), 7).value(), test2_7_expected) == 0);
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper " + "bound", cmp.compare(truncateStringMax(Literal.of(test3), 3).value(), test3) >= 0);
    Assert.assertTrue("Output must have three characters and the third character of the input must " + "be incremented. The second perceivable character in this string is actually a glyph. It consists of " + "two unicode characters", cmp.compare(truncateStringMax(Literal.of(test3), 3).value(), test3_3_expected) == 0);
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper bound", cmp.compare(truncateStringMax(Literal.of(test4), 1).value(), test4) >= 0);
    Assert.assertTrue("Output must have one character. Since the first character is the max 3 byte " + "UTF-8 character, it should be incremented to the lowest 4 byte UTF-8 character", cmp.compare(truncateStringMax(Literal.of(test4), 1).value(), test4_1_expected) == 0);
    Assert.assertNull("An upper bound doesn't exist since the first two characters are max UTF-8 " + "characters", truncateStringMax(Literal.of(test5), 1));
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper bound", cmp.compare(truncateStringMax(Literal.of(test6), 2).value(), test6) >= 0);
    Assert.assertTrue("Test 4 byte UTF-8 character increment. Output must have one character with " + "the first character incremented", cmp.compare(truncateStringMax(Literal.of(test6), 1).value(), test6_2_expected) == 0);
    Assert.assertTrue("Truncated upper bound should be greater than or equal to the actual upper bound", cmp.compare(truncateStringMax(Literal.of(test7), 2).value(), test7) >= 0);
    Assert.assertTrue("Test input with multiple 4 byte UTF-8 character where the second unicode " + "character should be incremented", cmp.compare(truncateStringMax(Literal.of(test7), 2).value(), test7_2_expected) == 0);
    Assert.assertTrue("Test input with multiple 4 byte UTF-8 character where the first unicode " + "character should be incremented", cmp.compare(truncateStringMax(Literal.of(test7), 1).value(), test7_1_expected) == 0);
}

@Test
public void testGenerateMicroBatch() {
    add(table.newAppend(), files("A", "B", "C", "D", "E"));
    MicroBatch batch = MicroBatches.from(table.snapshot(1L), table.io()).specsById(table.specs()).generate(0, Long.MAX_VALUE, true);
    Assert.assertEquals(batch.snapshotId(), 1L);
    Assert.assertEquals(batch.startFileIndex(), 0);
    Assert.assertEquals(batch.endFileIndex(), 5);
    Assert.assertEquals(batch.sizeInBytes(), 50);
    Assert.assertTrue(batch.lastIndexOfSnapshot());
    filesMatch(Lists.newArrayList("A", "B", "C", "D", "E"), filesToScan(batch.tasks()));
    MicroBatch batch1 = MicroBatches.from(table.snapshot(1L), table.io()).specsById(table.specs()).generate(0, 15L, true);
    Assert.assertEquals(batch1.endFileIndex(), 1);
    Assert.assertEquals(batch1.sizeInBytes(), 10);
    Assert.assertFalse(batch1.lastIndexOfSnapshot());
    filesMatch(Lists.newArrayList("A"), filesToScan(batch1.tasks()));
    MicroBatch batch2 = MicroBatches.from(table.snapshot(1L), table.io()).specsById(table.specs()).generate(batch1.endFileIndex(), 30L, true);
    Assert.assertEquals(batch2.endFileIndex(), 4);
    Assert.assertEquals(batch2.sizeInBytes(), 30);
    Assert.assertFalse(batch2.lastIndexOfSnapshot());
    filesMatch(Lists.newArrayList("B", "C", "D"), filesToScan(batch2.tasks()));
    MicroBatch batch3 = MicroBatches.from(table.snapshot(1L), table.io()).specsById(table.specs()).generate(batch2.endFileIndex(), 50L, true);
    Assert.assertEquals(batch3.endFileIndex(), 5);
    Assert.assertEquals(batch3.sizeInBytes(), 10);
    Assert.assertTrue(batch3.lastIndexOfSnapshot());
    filesMatch(Lists.newArrayList("E"), filesToScan(batch3.tasks()));
}

@Test
public void testGenerateMicroBatchWithSmallTargetSize() {
    add(table.newAppend(), files("A", "B", "C", "D", "E"));
    MicroBatch batch = MicroBatches.from(table.snapshot(1L), table.io()).specsById(table.specs()).generate(0, 10L, true);
    Assert.assertEquals(batch.snapshotId(), 1L);
    Assert.assertEquals(batch.startFileIndex(), 0);
    Assert.assertEquals(batch.endFileIndex(), 1);
    Assert.assertEquals(batch.sizeInBytes(), 10);
    Assert.assertFalse(batch.lastIndexOfSnapshot());
    filesMatch(Lists.newArrayList("A"), filesToScan(batch.tasks()));
    MicroBatch batch1 = MicroBatches.from(table.snapshot(1L), table.io()).specsById(table.specs()).generate(batch.endFileIndex(), 5L, true);
    Assert.assertEquals(batch1.endFileIndex(), 2);
    Assert.assertEquals(batch1.sizeInBytes(), 10);
    filesMatch(Lists.newArrayList("B"), filesToScan(batch1.tasks()));
    Assert.assertFalse(batch1.lastIndexOfSnapshot());
    MicroBatch batch2 = MicroBatches.from(table.snapshot(1L), table.io()).specsById(table.specs()).generate(batch1.endFileIndex(), 10L, true);
    Assert.assertEquals(batch2.endFileIndex(), 3);
    Assert.assertEquals(batch2.sizeInBytes(), 10);
    filesMatch(Lists.newArrayList("C"), filesToScan(batch2.tasks()));
    Assert.assertFalse(batch2.lastIndexOfSnapshot());
    MicroBatch batch3 = MicroBatches.from(table.snapshot(1L), table.io()).specsById(table.specs()).generate(batch2.endFileIndex(), 10L, true);
    Assert.assertEquals(batch3.endFileIndex(), 4);
    Assert.assertEquals(batch3.sizeInBytes(), 10);
    filesMatch(Lists.newArrayList("D"), filesToScan(batch3.tasks()));
    Assert.assertFalse(batch3.lastIndexOfSnapshot());
    MicroBatch batch4 = MicroBatches.from(table.snapshot(1L), table.io()).specsById(table.specs()).generate(batch3.endFileIndex(), 5L, true);
    Assert.assertEquals(batch4.endFileIndex(), 5);
    Assert.assertEquals(batch4.sizeInBytes(), 10);
    filesMatch(Lists.newArrayList("E"), filesToScan(batch4.tasks()));
    Assert.assertTrue(batch4.lastIndexOfSnapshot());
