@Test
public void testExpireWithDeleteFiles() {
    Assume.assumeTrue("Delete files only supported in V2 spec", formatVersion == 2);
    // Data Manifest => File_A
    table.newAppend().appendFile(FILE_A).commit();
    Snapshot firstSnapshot = table.currentSnapshot();
    // Data Manifest => FILE_A
    // Delete Manifest => FILE_A_DELETES
    table.newRowDelta().addDeletes(FILE_A_DELETES).commit();
    Snapshot secondSnapshot = table.currentSnapshot();
    Assert.assertEquals("Should have 1 data manifest", 1, secondSnapshot.dataManifests().size());
    Assert.assertEquals("Should have 1 delete manifest", 1, secondSnapshot.deleteManifests().size());
    // FILE_A and FILE_A_DELETES move into "DELETED" state
    table.newRewrite().rewriteFiles(// deleted
    ImmutableSet.of(FILE_A), // deleted
    ImmutableSet.of(FILE_A_DELETES), ImmutableSet.of(FILE_B), // added
    ImmutableSet.of(FILE_B_DELETES)).validateFromSnapshot(secondSnapshot.snapshotId()).commit();
    Snapshot thirdSnapshot = table.currentSnapshot();
    Set<ManifestFile> manifestOfDeletedFiles = thirdSnapshot.allManifests().stream().filter(ManifestFile::hasDeletedFiles).collect(Collectors.toSet());
    Assert.assertEquals("Should have two manifests of deleted files", 2, manifestOfDeletedFiles.size());
    // Need one more commit before manifests of files of DELETED state get cleared from current snapshot.
    table.newAppend().appendFile(FILE_C).commit();
    Snapshot fourthSnapshot = table.currentSnapshot();
    long fourthSnapshotTs = waitUntilAfter(fourthSnapshot.timestampMillis());
    Set<String> deletedFiles = Sets.newHashSet();
    table.expireSnapshots().expireOlderThan(fourthSnapshotTs).deleteWith(deletedFiles::add).commit();
    Assert.assertEquals("Should remove old delete files and delete file manifests", ImmutableSet.builder().add(FILE_A.path()).add(FILE_A_DELETES.path()).add(firstSnapshot.manifestListLocation()).add(secondSnapshot.manifestListLocation()).add(thirdSnapshot.manifestListLocation()).addAll(secondSnapshot.allManifests().stream().map(ManifestFile::path).collect(Collectors.toList())).addAll(manifestOfDeletedFiles.stream().map(ManifestFile::path).collect(Collectors.toList())).build(), deletedFiles);
}

