public void testWithMultiplePartitionSpec() throws IOException {
    Assert.assertNull("Table should be empty", table.currentSnapshot());
    table.newAppend().appendFile(FILE_A).appendFile(FILE_B).commit();
    TableMetadata base = readMetadata();
    Assert.assertEquals("Should create 1 manifest for initial write", 1, base.currentSnapshot().allManifests().size());
    ManifestFile initialManifest = base.currentSnapshot().allManifests().get(0);
    int initialPartitionSpecId = initialManifest.partitionSpecId();
    // build the new spec using the table's schema, which uses fresh IDs
    PartitionSpec newSpec = PartitionSpec.builderFor(base.schema()).bucket("data", 16).bucket("id", 4).build();
    // commit the new partition spec to the table manually
    table.ops().commit(base, base.updatePartitionSpec(newSpec));
    DataFile newFileY = DataFiles.builder(table.spec()).withPath("/path/to/data-y.parquet").withFileSizeInBytes(10).withPartitionPath("data_bucket=2/id_bucket=3").withRecordCount(1).build();
    table.newAppend().appendFile(newFileY).commit();
    DataFile newFileZ = DataFiles.builder(table.spec()).withPath("/path/to/data-z.parquet").withFileSizeInBytes(10).withPartitionPath("data_bucket=2/id_bucket=4").withRecordCount(1).build();
    table.newAppend().appendFile(newFileZ).commit();
    Assert.assertEquals("Should use 3 manifest files", 3, table.currentSnapshot().allManifests().size());
    RewriteManifests rewriteManifests = table.rewriteManifests();
    // try to cluster in 1 manifest file, but because of 2 partition specs
    // we should still have 2 manifest files.
    rewriteManifests.clusterBy(dataFile -> "file").commit();
    List<ManifestFile> manifestFiles = table.currentSnapshot().allManifests();
    Assert.assertEquals("Rewrite manifest should produce 2 manifest files", 2, manifestFiles.size());
    Assert.assertEquals("2 manifest files should have different partitionSpecId", true, manifestFiles.get(0).partitionSpecId() != manifestFiles.get(1).partitionSpecId());
    matchNumberOfManifestFileWithSpecId(manifestFiles, initialPartitionSpecId, 1);
    matchNumberOfManifestFileWithSpecId(manifestFiles, table.ops().current().spec().specId(), 1);
    Assert.assertEquals("first manifest file should have 2 data files", Integer.valueOf(2), manifestFiles.get(0).existingFilesCount());
    Assert.assertEquals("second manifest file should have 2 data files", Integer.valueOf(2), manifestFiles.get(1).existingFilesCount());
}

