    File location = temp.newFolder();
    // should be created by table create
    Assert.assertTrue(location.delete());
    Table table = TestTables.create(location, "test", SCHEMA, SPEC, formatVersion);
    DataFile fileOne = createDataFile("one");
    DataFile fileTwo = createDataFile("two");
    table.newAppend().appendFile(fileOne).appendFile(fileTwo).commit();
    List<FileScanTask> tasks = Lists.newArrayList(table.newScan().filter(Expressions.equal("part", "one")).planFiles());
    Assert.assertEquals("Should produce 1 matching file task", 1, tasks.size());
    table.updateSchema().renameColumn("part", "p").commit();
    // plan the scan using the new name in a filter
    tasks = Lists.newArrayList(table.newScan().filter(Expressions.equal("p", "one")).planFiles());
    Assert.assertEquals("Should produce 1 matching file task", 1, tasks.size());
}

@Test
public void testSnapshotTimeRangeValidation() {
    long t0 = System.currentTimeMillis();
    table.newAppend().appendFile(// data_bucket=0
    FILE_A).appendFile(// data_bucket=1
    FILE_B).commit();
    long t1 = System.currentTimeMillis();
    while (t1 <= table.currentSnapshot().timestampMillis()) {
        t1 = System.currentTimeMillis();
    }
    table.newAppend().appendFile(// data_bucket=2
    FILE_C).commit();
    long secondSnapshotId = table.currentSnapshot().snapshotId();
    long t2 = System.currentTimeMillis();
    while (t2 <= table.currentSnapshot().timestampMillis()) {
        t2 = System.currentTimeMillis();
    }
    // expire the first snapshot
    table.expireSnapshots().expireOlderThan(t1).commit();
    Assert.assertEquals("Should have one snapshot", 1, Lists.newArrayList(table.snapshots()).size());
    Assert.assertEquals("Snapshot should be the second snapshot created", secondSnapshotId, table.currentSnapshot().snapshotId());
    // this should include the first snapshot, but it was removed from the dataset
    TableScan scan = table.newScan().filter(greaterThanOrEqual("dateCreated", t0)).filter(lessThan("dateCreated", t2));
    AssertHelpers.assertThrows("Should fail summary because range may include expired snapshots", IllegalArgumentException.class, "may include expired snapshots", () -> new ScanSummary.Builder(scan).build());
}

@Test
public void testTimestampRanges() {
    long lower = 1542750188523L;
    long upper = 1542750695131L;
    Assert.assertEquals("Should use inclusive bound", Pair.of(Long.MIN_VALUE, upper), timestampRange(ImmutableList.of(lessThanOrEqual("ts_ms", upper))));
    Assert.assertEquals("Should use lower value for upper bound", Pair.of(Long.MIN_VALUE, upper), timestampRange(ImmutableList.of(lessThanOrEqual("ts_ms", upper + 918234), lessThanOrEqual("ts_ms", upper))));
    Assert.assertEquals("Should make upper bound inclusive", Pair.of(Long.MIN_VALUE, upper - 1), timestampRange(ImmutableList.of(lessThan("ts_ms", upper))));
    Assert.assertEquals("Should use inclusive bound", Pair.of(lower, Long.MAX_VALUE), timestampRange(ImmutableList.of(greaterThanOrEqual("ts_ms", lower))));
    Assert.assertEquals("Should use upper value for lower bound", Pair.of(lower, Long.MAX_VALUE), timestampRange(ImmutableList.of(greaterThanOrEqual("ts_ms", lower - 918234), greaterThanOrEqual("ts_ms", lower))));
    Assert.assertEquals("Should make lower bound inclusive", Pair.of(lower + 1, Long.MAX_VALUE), timestampRange(ImmutableList.of(greaterThan("ts_ms", lower))));
    Assert.assertEquals("Should set both bounds for equals", Pair.of(lower, lower), timestampRange(ImmutableList.of(equal("ts_ms", lower))));
    Assert.assertEquals("Should set both bounds", Pair.of(lower, upper - 1), timestampRange(ImmutableList.of(greaterThanOrEqual("ts_ms", lower), lessThan("ts_ms", upper))));
    // >= lower and < lower is an empty range
    AssertHelpers.assertThrows("Should reject empty ranges", IllegalArgumentException.class, "No timestamps can match filters", () -> timestampRange(ImmutableList.of(greaterThanOrEqual("ts_ms", lower), lessThan("ts_ms", lower))));
}

