@Test
public void testNoChange() {
    int onlyId = table.schema().schemaId();
    Map<Integer, Schema> onlySchemaMap = schemaMap(table.schema());
    // add files to table
    table.newAppend().appendFile(FILE_A).appendFile(FILE_B).commit();
    TestHelpers.assertSameSchemaMap(onlySchemaMap, table.schemas());
    Assert.assertEquals("Current snapshot's schemaId should be the current", table.schema().schemaId(), (int) table.currentSnapshot().schemaId());
    Assert.assertEquals("Schema ids should be correct in snapshots", ImmutableList.of(onlyId), Lists.transform(Lists.newArrayList(table.snapshots()), Snapshot::schemaId));
    // remove file from table
    table.newDelete().deleteFile(FILE_A).commit();
    TestHelpers.assertSameSchemaMap(onlySchemaMap, table.schemas());
    Assert.assertEquals("Current snapshot's schemaId should be the current", table.schema().schemaId(), (int) table.currentSnapshot().schemaId());
    Assert.assertEquals("Schema ids should be correct in snapshots", ImmutableList.of(onlyId, onlyId), Lists.transform(Lists.newArrayList(table.snapshots()), Snapshot::schemaId));
    // add file to table
    table.newFastAppend().appendFile(FILE_A2).commit();
    TestHelpers.assertSameSchemaMap(onlySchemaMap, table.schemas());
    Assert.assertEquals("Current snapshot's schemaId should be the current", table.schema().schemaId(), (int) table.currentSnapshot().schemaId());
    Assert.assertEquals("Schema ids should be correct in snapshots", ImmutableList.of(onlyId, onlyId, onlyId), Lists.transform(Lists.newArrayList(table.snapshots()), Snapshot::schemaId));
}

@Test
public void testSchemaIdChangeInSchemaUpdate() {
    Schema originalSchema = table.schema();
    // add files to table
    table.newAppend().appendFile(FILE_A).appendFile(FILE_B).commit();
    TestHelpers.assertSameSchemaMap(schemaMap(table.schema()), table.schemas());
    Assert.assertEquals("Current snapshot's schemaId should be the current", table.schema().schemaId(), (int) table.currentSnapshot().schemaId());
    Assert.assertEquals("Schema ids should be correct in snapshots", ImmutableList.of(originalSchema.schemaId()), Lists.transform(Lists.newArrayList(table.snapshots()), Snapshot::schemaId));
    // update schema
    table.updateSchema().addColumn("data2", Types.StringType.get()).commit();
    Schema updatedSchema = new Schema(1, required(1, "id", Types.IntegerType.get()), required(2, "data", Types.StringType.get()), optional(3, "data2", Types.StringType.get()));
    TestHelpers.assertSameSchemaMap(schemaMap(originalSchema, updatedSchema), table.schemas());
    Assert.assertEquals("Current snapshot's schemaId should be old since update schema doesn't create new snapshot", originalSchema.schemaId(), (int) table.currentSnapshot().schemaId());
    Assert.assertEquals("Current schema should match", updatedSchema.asStruct(), table.schema().asStruct());
    Assert.assertEquals("Schema ids should be correct in snapshots", ImmutableList.of(originalSchema.schemaId()), Lists.transform(Lists.newArrayList(table.snapshots()), Snapshot::schemaId));
    // remove file from table
    table.newDelete().deleteFile(FILE_A).commit();
    TestHelpers.assertSameSchemaMap(schemaMap(originalSchema, updatedSchema), table.schemas());
    Assert.assertEquals("Current snapshot's schemaId should be the current", updatedSchema.schemaId(), (int) table.currentSnapshot().schemaId());
    Assert.assertEquals("Current schema should match", updatedSchema.asStruct(), table.schema().asStruct());
    Assert.assertEquals("Schema ids should be correct in snapshots", ImmutableList.of(originalSchema.schemaId(), updatedSchema.schemaId()), Lists.transform(Lists.newArrayList(table.snapshots()), Snapshot::schemaId));
    // add files to table
    table.newAppend().appendFile(FILE_A2).commit();
    TestHelpers.assertSameSchemaMap(schemaMap(originalSchema, updatedSchema), table.schemas());
    Assert.assertEquals("Current snapshot's schemaId should be the current", updatedSchema.schemaId(), (int) table.currentSnapshot().schemaId());
    Assert.assertEquals("Current schema should match", updatedSchema.asStruct(), table.schema().asStruct());
    Assert.assertEquals("Schema ids should be correct in snapshots", ImmutableList.of(originalSchema.schemaId(), updatedSchema.schemaId(), updatedSchema.schemaId()), Lists.transform(Lists.newArrayList(table.snapshots()), Snapshot::schemaId));
}

