    AssertHelpers.assertThrows("Creating schema with float identifier field should fail", IllegalArgumentException.class, "Cannot add field float as an identifier field: must not be float or double field", () -> new Schema(testSchema.asStruct().fields(), ImmutableSet.of(2)));
    AssertHelpers.assertThrows("Creating schema with double identifier field should fail", IllegalArgumentException.class, "Cannot add field double as an identifier field: must not be float or double field", () -> new Schema(testSchema.asStruct().fields(), ImmutableSet.of(3)));
    AssertHelpers.assertThrows("add a field with name not exist should fail", IllegalArgumentException.class, "not found in current schema or added columns", () -> new SchemaUpdate(SCHEMA, SCHEMA_LAST_COLUMN_ID).setIdentifierFields("unknown").apply());
    AssertHelpers.assertThrows("add a field of non-primitive type should fail", IllegalArgumentException.class, "not a primitive type field", () -> new SchemaUpdate(SCHEMA, SCHEMA_LAST_COLUMN_ID).setIdentifierFields("locations").apply());
    AssertHelpers.assertThrows("add an optional field should fail", IllegalArgumentException.class, "not a required field", () -> new SchemaUpdate(SCHEMA, SCHEMA_LAST_COLUMN_ID).setIdentifierFields("data").apply());
    AssertHelpers.assertThrows("add a map key nested field should fail", IllegalArgumentException.class, "must not be nested in " + SCHEMA.findField("locations"), () -> new SchemaUpdate(SCHEMA, SCHEMA_LAST_COLUMN_ID).setIdentifierFields("locations.key.zip").apply());
    AssertHelpers.assertThrows("add a nested field in list should fail", IllegalArgumentException.class, "must not be nested in " + SCHEMA.findField("points"), () -> new SchemaUpdate(SCHEMA, SCHEMA_LAST_COLUMN_ID).setIdentifierFields("points.element.x").apply());
    Schema newSchema = new SchemaUpdate(SCHEMA, SCHEMA_LAST_COLUMN_ID).allowIncompatibleChanges().addRequiredColumn("col_float", Types.FloatType.get()).addRequiredColumn("col_double", Types.DoubleType.get()).addRequiredColumn("new", Types.StructType.of(Types.NestedField.required(SCHEMA_LAST_COLUMN_ID + 4, "fields", Types.ListType.ofRequired(SCHEMA_LAST_COLUMN_ID + 5, Types.StructType.of(Types.NestedField.required(SCHEMA_LAST_COLUMN_ID + 6, "nested", Types.StringType.get())))))).addRequiredColumn("new_map", Types.MapType.ofRequired(SCHEMA_LAST_COLUMN_ID + 8, SCHEMA_LAST_COLUMN_ID + 9, Types.StructType.of(required(SCHEMA_LAST_COLUMN_ID + 10, "key_col", Types.StringType.get())), Types.StructType.of(required(SCHEMA_LAST_COLUMN_ID + 11, "val_col", Types.StringType.get()))), "map of address to coordinate").addRequiredColumn("required_list", Types.ListType.ofRequired(SCHEMA_LAST_COLUMN_ID + 13, Types.StructType.of(required(SCHEMA_LAST_COLUMN_ID + 14, "x", Types.LongType.get()), required(SCHEMA_LAST_COLUMN_ID + 15, "y", Types.LongType.get())))).apply();
    int lastColId = SCHEMA_LAST_COLUMN_ID + 15;
