    Assert.assertEquals("Previous snapshot files should match", previousSnapshot.allManifests(), metadata.snapshot(previousSnapshotId).allManifests());
    Assert.assertNull("Previous snapshot's schema ID should be null", metadata.snapshot(previousSnapshotId).schemaId());
