    Assert.assertEquals("Should use TableMetadata.INITIAL_SCHEMA_ID for current schema id", TableMetadata.INITIAL_SCHEMA_ID, freshTable.currentSchemaId());
    assertSameSchemaList(ImmutableList.of(schema), freshTable.schemas());
    Assert.assertEquals("Should have expected schema upon return", schema.asStruct(), freshTable.schema().asStruct());
    Assert.assertEquals("Should return expected last column id", 1, freshTable.lastColumnId());
    // update schema
    Schema schema2 = new Schema(Types.NestedField.required(1, "y", Types.LongType.get(), "comment"), Types.NestedField.required(2, "x", Types.StringType.get()));
    TableMetadata twoSchemasTable = freshTable.updateSchema(schema2, 2);
    Assert.assertEquals("Should have current schema id as 1", 1, twoSchemasTable.currentSchemaId());
    assertSameSchemaList(ImmutableList.of(schema, new Schema(1, schema2.columns())), twoSchemasTable.schemas());
    Assert.assertEquals("Should have expected schema upon return", schema2.asStruct(), twoSchemasTable.schema().asStruct());
    Assert.assertEquals("Should return expected last column id", 2, twoSchemasTable.lastColumnId());
    // update schema with the the same schema and last column ID as current shouldn't cause change
    Schema sameSchema2 = new Schema(Types.NestedField.required(1, "y", Types.LongType.get(), "comment"), Types.NestedField.required(2, "x", Types.StringType.get()));
    TableMetadata sameSchemaTable = twoSchemasTable.updateSchema(sameSchema2, 2);
    Assert.assertSame("Should return same table metadata", twoSchemasTable, sameSchemaTable);
    // update schema with the the same schema and different last column ID as current should create a new table
    TableMetadata differentColumnIdTable = sameSchemaTable.updateSchema(sameSchema2, 3);
    Assert.assertEquals("Should have current schema id as 1", 1, differentColumnIdTable.currentSchemaId());
    assertSameSchemaList(ImmutableList.of(schema, new Schema(1, schema2.columns())), differentColumnIdTable.schemas());
    Assert.assertEquals("Should have expected schema upon return", schema2.asStruct(), differentColumnIdTable.schema().asStruct());
    Assert.assertEquals("Should return expected last column id", 3, differentColumnIdTable.lastColumnId());
    // update schema with old schema does not change schemas
    TableMetadata revertSchemaTable = differentColumnIdTable.updateSchema(schema, 3);
    Assert.assertEquals("Should have current schema id as 0", 0, revertSchemaTable.currentSchemaId());
    assertSameSchemaList(ImmutableList.of(schema, new Schema(1, schema2.columns())), revertSchemaTable.schemas());
    Assert.assertEquals("Should have expected schema upon return", schema.asStruct(), revertSchemaTable.schema().asStruct());
    Assert.assertEquals("Should return expected last column id", 3, revertSchemaTable.lastColumnId());
    // create new schema will use the largest schema id + 1
    Schema schema3 = new Schema(Types.NestedField.required(2, "y", Types.LongType.get(), "comment"), Types.NestedField.required(4, "x", Types.StringType.get()), Types.NestedField.required(6, "z", Types.IntegerType.get()));
    TableMetadata threeSchemaTable = revertSchemaTable.updateSchema(schema3, 6);
    Assert.assertEquals("Should have current schema id as 2", 2, threeSchemaTable.currentSchemaId());
    assertSameSchemaList(ImmutableList.of(schema, new Schema(1, schema2.columns()), new Schema(2, schema3.columns())), threeSchemaTable.schemas());
    Assert.assertEquals("Should have expected schema upon return", schema3.asStruct(), threeSchemaTable.schema().asStruct());
    Assert.assertEquals("Should return expected last column id", 6, threeSchemaTable.lastColumnId());
}

