    Assert.assertEquals("Should merge both commit manifests into a single manifest", 1, table.currentSnapshot().allManifests().size());
    Assert.assertFalse("Should merge both commit manifests into a new manifest", previousManifests.contains(table.currentSnapshot().allManifests().get(0)));
