@Test
public void testTransactionRewriteManifestsAppendedDirectly() throws IOException {
    Table table = load();
    table.updateProperties().set(TableProperties.SNAPSHOT_ID_INHERITANCE_ENABLED, "true").set(TableProperties.MANIFEST_MIN_MERGE_COUNT, "0").commit();
    table.newFastAppend().appendFile(FILE_A).commit();
    long firstSnapshotId = table.currentSnapshot().snapshotId();
    table.newFastAppend().appendFile(FILE_B).commit();
    long secondSnapshotId = table.currentSnapshot().snapshotId();
    List<ManifestFile> manifests = table.currentSnapshot().allManifests();
    Assert.assertEquals("Should have 2 manifests after 2 appends", 2, manifests.size());
    ManifestFile newManifest = writeManifest("manifest-file-1.avro", manifestEntry(ManifestEntry.Status.EXISTING, firstSnapshotId, FILE_A), manifestEntry(ManifestEntry.Status.EXISTING, secondSnapshotId, FILE_B));
    Transaction txn = table.newTransaction();
    txn.rewriteManifests().deleteManifest(manifests.get(0)).deleteManifest(manifests.get(1)).addManifest(newManifest).commit();
    txn.newAppend().appendFile(FILE_C).commit();
    txn.commitTransaction();
    long finalSnapshotId = table.currentSnapshot().snapshotId();
    long finalSnapshotTimestamp = System.currentTimeMillis();
    Assert.assertTrue("Append manifest should not be deleted", new File(newManifest.path()).exists());
    List<ManifestFile> finalManifests = table.currentSnapshot().allManifests();
    Assert.assertEquals("Should have 1 final manifest", 1, finalManifests.size());
    validateManifestEntries(finalManifests.get(0), ids(finalSnapshotId, firstSnapshotId, secondSnapshotId), files(FILE_C, FILE_A, FILE_B), statuses(ManifestEntry.Status.ADDED, ManifestEntry.Status.EXISTING, ManifestEntry.Status.EXISTING));
    table.expireSnapshots().expireOlderThan(finalSnapshotTimestamp + 1).retainLast(1).commit();
    Assert.assertFalse("Append manifest should be deleted on expiry", new File(newManifest.path()).exists());
}

