    List<Boolean> results = IntStream.range(0, 3).parallel().mapToObj(i -> {
        String owner = UUID.randomUUID().toString();
        boolean succeeded = lockManager.acquire(lockEntityId, owner);
        if (succeeded) {
            try {
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
            Assert.assertTrue(lockManager.release(lockEntityId, owner));
        }
        return succeeded;
    }).collect(Collectors.toList());
    Assert.assertEquals("all lock acquire should succeed sequentially", 3, results.stream().filter(s -> s).count());
    Assert.assertTrue("must take more than 3 seconds", System.currentTimeMillis() - start >= 3000);
}

