@Test
public void writeAndValidateTimestamps() throws IOException {
    TimeZone currentTz = TimeZone.getDefault();
    try {
        Schema timestampSchema = new Schema(required(1, "tsTzCol", Types.TimestampType.withZone()), required(2, "tsCol", Types.TimestampType.withoutZone()));
        // Write using America/New_York timezone
        TimeZone.setDefault(TimeZone.getTimeZone("America/New_York"));
        GenericRecord record1 = GenericRecord.create(timestampSchema);
        record1.setField("tsTzCol", OffsetDateTime.parse("2017-01-16T17:10:34-08:00"));
        record1.setField("tsCol", LocalDateTime.parse("1970-01-01T00:01:00"));
        GenericRecord record2 = GenericRecord.create(timestampSchema);
        record2.setField("tsTzCol", OffsetDateTime.parse("2017-05-16T17:10:34-08:00"));
        record2.setField("tsCol", LocalDateTime.parse("1970-05-01T00:01:00"));
        GenericRecord record3 = GenericRecord.create(timestampSchema);
        record3.setField("tsTzCol", OffsetDateTime.parse("1935-01-16T17:10:34-08:00"));
        record3.setField("tsCol", LocalDateTime.parse("1935-01-01T00:01:00"));
        GenericRecord record4 = GenericRecord.create(timestampSchema);
        record4.setField("tsTzCol", OffsetDateTime.parse("1935-05-16T17:10:34-08:00"));
        record4.setField("tsCol", LocalDateTime.parse("1935-05-01T00:01:00"));
        File testFile = temp.newFile();
        Assert.assertTrue("Delete should succeed", testFile.delete());
        try (FileAppender<Record> writer = ORC.write(Files.localOutput(testFile)).schema(timestampSchema).createWriterFunc(GenericOrcWriter::buildWriter).build()) {
            writer.add(record1);
            writer.add(record2);
            writer.add(record3);
            writer.add(record4);
        }
        // Read using Asia/Kolkata timezone
        TimeZone.setDefault(TimeZone.getTimeZone("Asia/Kolkata"));
        List<Record> rows;
        try (CloseableIterable<Record> reader = ORC.read(Files.localInput(testFile)).project(timestampSchema).createReaderFunc(fileSchema -> GenericOrcReader.buildReader(timestampSchema, fileSchema)).build()) {
            rows = Lists.newArrayList(reader);
        }
        Assert.assertEquals(OffsetDateTime.parse("2017-01-17T01:10:34Z"), rows.get(0).getField("tsTzCol"));
        Assert.assertEquals(LocalDateTime.parse("1970-01-01T00:01:00"), rows.get(0).getField("tsCol"));
        Assert.assertEquals(OffsetDateTime.parse("2017-05-17T01:10:34Z"), rows.get(1).getField("tsTzCol"));
        Assert.assertEquals(LocalDateTime.parse("1970-05-01T00:01:00"), rows.get(1).getField("tsCol"));
        Assert.assertEquals(OffsetDateTime.parse("1935-01-17T01:10:34Z"), rows.get(2).getField("tsTzCol"));
        Assert.assertEquals(LocalDateTime.parse("1935-01-01T00:01:00"), rows.get(2).getField("tsCol"));
        Assert.assertEquals(OffsetDateTime.parse("1935-05-17T01:10:34Z"), rows.get(3).getField("tsTzCol"));
        Assert.assertEquals(LocalDateTime.parse("1935-05-01T00:01:00"), rows.get(3).getField("tsCol"));
    } finally {
        TimeZone.setDefault(currentTz);
    }
}

@Test
public void writeAndValidateExternalData() throws IOException {
    File testFile = temp.newFile();
    Assert.assertTrue("Delete should succeed", testFile.delete());
    Configuration conf = new Configuration();
    TypeDescription writerSchema = TypeDescription.fromString("struct<a:tinyint,b:smallint,c:char(10),d:varchar(10)>");
    Writer writer = OrcFile.createWriter(new Path(testFile.toString()), OrcFile.writerOptions(conf).setSchema(writerSchema));
    VectorizedRowBatch batch = writerSchema.createRowBatch();
    batch.ensureSize(1);
    batch.size = 1;
    ((LongColumnVector) batch.cols[0]).vector[0] = 1;
    ((LongColumnVector) batch.cols[1]).vector[0] = 123;
    ((BytesColumnVector) batch.cols[2]).setVal(0, "1".getBytes(StandardCharsets.UTF_8));
    ((BytesColumnVector) batch.cols[3]).setVal(0, "123".getBytes(StandardCharsets.UTF_8));
    writer.addRowBatch(batch);
    writer.close();
    List<Record> rows;
    Schema readSchema = new Schema(optional(1, "a", Types.IntegerType.get()), optional(2, "b", Types.IntegerType.get()), optional(3, "c", Types.StringType.get()), optional(4, "d", Types.StringType.get()));
    try (CloseableIterable<Record> reader = ORC.read(Files.localInput(testFile)).project(readSchema).createReaderFunc(fileSchema -> GenericOrcReader.buildReader(readSchema, fileSchema)).build()) {
        rows = Lists.newArrayList(reader);
    }
    Assert.assertEquals(1, rows.get(0).getField("a"));
    Assert.assertEquals(123, rows.get(0).getField("b"));
    Assert.assertEquals("1", rows.get(0).getField("c"));
    Assert.assertEquals("123", rows.get(0).getField("d"));
}

@Test
public void testDataWriter() throws IOException {
    OutputFile file = Files.localOutput(temp.newFile());
    SortOrder sortOrder = SortOrder.builderFor(SCHEMA).withOrderId(10).asc("id").build();
    DataWriter<Record> dataWriter = ORC.writeData(file).schema(SCHEMA).createWriterFunc(GenericOrcWriter::buildWriter).overwrite().withSpec(PartitionSpec.unpartitioned()).withSortOrder(sortOrder).build();
    try {
        for (Record record : records) {
            dataWriter.write(record);
        }
    } finally {
        dataWriter.close();
    }
    DataFile dataFile = dataWriter.toDataFile();
    Assert.assertEquals("Format should be ORC", FileFormat.ORC, dataFile.format());
    Assert.assertEquals("Should be data file", FileContent.DATA, dataFile.content());
    Assert.assertEquals("Record count should match", records.size(), dataFile.recordCount());
    Assert.assertEquals("Partition should be empty", 0, dataFile.partition().size());
    Assert.assertEquals("Sort order should match", sortOrder.orderId(), (int) dataFile.sortOrderId());
    Assert.assertNull("Key metadata should be null", dataFile.keyMetadata());
    List<Record> writtenRecords;
    try (CloseableIterable<Record> reader = ORC.read(file.toInputFile()).project(SCHEMA).createReaderFunc(fileSchema -> GenericOrcReader.buildReader(SCHEMA, fileSchema)).build()) {
        writtenRecords = Lists.newArrayList(reader);
    }
    Assert.assertEquals("Written records should match", records, writtenRecords);
}

