@Test
public void testProjectWithMissingFilterColumn() {
    Iterable<Record> results = IcebergGenerics.read(sharedTable).where(Expressions.greaterThanOrEqual("id", 1)).where(Expressions.lessThan("id", 21)).select("data").build();
    Set<String> expected = Sets.newHashSet();
    for (Record record : concat(file1FirstSnapshotRecords, file2FirstSnapshotRecords, file3FirstSnapshotRecords)) {
        Long id = (Long) record.getField("id");
        if (id >= 1 && id < 21) {
            expected.add(record.getField("data").toString());
        }
    }
    results.forEach(record -> Assert.assertEquals("Record should have two projected fields", 2, record.size()));
    Assert.assertEquals("Should project correct rows", expected, Sets.newHashSet(transform(results, record -> record.getField("data").toString())));
}

