    Schema partialMapValue = new Schema(Types.NestedField.optional(7, "map", Types.MapType.ofOptional(5, 6, Types.StructType.of(Types.NestedField.required(1, "key", Types.LongType.get()), Types.NestedField.required(2, "keyData", Types.LongType.get())), Types.StructType.of(Types.NestedField.required(3, "value", Types.LongType.get())))));
