    Assert.assertEquals("Should not project id", 1, projected.getArity());
    Assert.assertFalse("Should project location", projected.isNullAt(0));
    Assert.assertEquals("Should project latitude", 52.995143f, projectedLocation.getFloat(0), 0.000001f);
    Assert.assertEquals("Should project longitude", -1.539054f, projectedLocation.getFloat(1), 0.000001f);
