        result = WriteResult.builder().addAll(testHarness.extractOutputValues()).build();
        Assert.assertEquals(0, result.deleteFiles().length);
        Assert.assertEquals(expectedDataFiles, result.dataFiles().length);
        // Commit the iceberg transaction.
        AppendFiles appendFiles = table.newAppend();
        Arrays.stream(result.dataFiles()).forEach(appendFiles::appendFile);
        appendFiles.commit();
        // Assert the table records.
        SimpleDataUtil.assertTableRecords(tablePath, Lists.newArrayList(SimpleDataUtil.createRecord(1, "hello"), SimpleDataUtil.createRecord(2, "world"), SimpleDataUtil.createRecord(3, "hello"), SimpleDataUtil.createRecord(4, "foo"), SimpleDataUtil.createRecord(5, "bar")));
