public void testReplacePartitions() throws Exception {
    Assume.assumeFalse("Flink unbounded streaming does not support overwrite operation", isStreamingJob);
    String tableName = "test_partition";
    sql("CREATE TABLE %s(id INT, data VARCHAR) PARTITIONED BY (data) WITH ('write.format.default'='%s')", tableName, format.name());
    try {
        Table partitionedTable = validationCatalog.loadTable(TableIdentifier.of(icebergNamespace, tableName));
        sql("INSERT INTO %s SELECT 1, 'a'", tableName);
        sql("INSERT INTO %s SELECT 2, 'b'", tableName);
        sql("INSERT INTO %s SELECT 3, 'c'", tableName);
        SimpleDataUtil.assertTableRecords(partitionedTable, Lists.newArrayList(SimpleDataUtil.createRecord(1, "a"), SimpleDataUtil.createRecord(2, "b"), SimpleDataUtil.createRecord(3, "c")));
        sql("INSERT OVERWRITE %s SELECT 4, 'b'", tableName);
        sql("INSERT OVERWRITE %s SELECT 5, 'a'", tableName);
        SimpleDataUtil.assertTableRecords(partitionedTable, Lists.newArrayList(SimpleDataUtil.createRecord(5, "a"), SimpleDataUtil.createRecord(4, "b"), SimpleDataUtil.createRecord(3, "c")));
        sql("INSERT OVERWRITE %s PARTITION (data='a') SELECT 6", tableName);
        SimpleDataUtil.assertTableRecords(partitionedTable, Lists.newArrayList(SimpleDataUtil.createRecord(6, "a"), SimpleDataUtil.createRecord(4, "b"), SimpleDataUtil.createRecord(3, "c")));
    } finally {
        sql("DROP TABLE IF EXISTS %s.%s", flinkDatabase, tableName);
    }
}

