@Test
public void testNestedMapTypeProjection() {
    Schema schema = new Schema(Types.NestedField.required(0, "id", Types.LongType.get()), Types.NestedField.optional(7, "map", Types.MapType.ofOptional(5, 6, Types.StructType.of(Types.NestedField.required(1, "key", Types.LongType.get()), Types.NestedField.required(2, "keyData", Types.LongType.get())), Types.StructType.of(Types.NestedField.required(3, "value", Types.LongType.get()), Types.NestedField.required(4, "valueData", Types.LongType.get())))));
    // Project id only.
    Schema idOnly = schema.select("id");
    generateAndValidate(schema, idOnly);
    // Project map only.
    Schema mapOnly = schema.select("map");
    generateAndValidate(schema, mapOnly);
    // Project all.
    generateAndValidate(schema, schema);
    // Project partial map key.
    Schema partialMapKey = new Schema(Types.NestedField.optional(7, "map", Types.MapType.ofOptional(5, 6, Types.StructType.of(Types.NestedField.required(1, "key", Types.LongType.get())), Types.StructType.of(Types.NestedField.required(3, "value", Types.LongType.get()), Types.NestedField.required(4, "valueData", Types.LongType.get())))));
    AssertHelpers.assertThrows("Should not allow to project a partial map key with non-primitive type.", IllegalArgumentException.class, "Cannot project a partial map key or value", () -> generateAndValidate(schema, partialMapKey));
    // Project partial map key.
    Schema partialMapValue = new Schema(Types.NestedField.optional(7, "map", Types.MapType.ofOptional(5, 6, Types.StructType.of(Types.NestedField.required(1, "key", Types.LongType.get()), Types.NestedField.required(2, "keyData", Types.LongType.get())), Types.StructType.of(Types.NestedField.required(3, "value", Types.LongType.get())))));
    AssertHelpers.assertThrows("Should not allow to project a partial map value with non-primitive type.", IllegalArgumentException.class, "Cannot project a partial map key or value", () -> generateAndValidate(schema, partialMapValue));
}

