@Test
public void testNestedProjection() throws Exception {
    Schema schema = new Schema(required(1, "data", Types.StringType.get()), required(2, "nested", Types.StructType.of(Types.NestedField.required(3, "f1", Types.StringType.get()), Types.NestedField.required(4, "f2", Types.StringType.get()), Types.NestedField.required(5, "f3", Types.LongType.get()))), required(6, "id", Types.LongType.get()));
