@Test
public void testHashDistributeMode() throws Exception {
    String tableName = "test_hash_distribution_mode";
    Map<String, String> tableProps = ImmutableMap.of("write.format.default", format.name(), TableProperties.WRITE_DISTRIBUTION_MODE, DistributionMode.HASH.modeName());
    // Initialize a BoundedSource table to precisely emit those rows in only one checkpoint.
    List<Row> dataSet = IntStream.range(1, 1000).mapToObj(i -> ImmutableList.of(Row.of(i, "aaa"), Row.of(i, "bbb"), Row.of(i, "ccc"))).flatMap(List::stream).collect(Collectors.toList());
    String dataId = BoundedTableFactory.registerDataSet(ImmutableList.of(dataSet));
    sql("CREATE TABLE %s(id INT NOT NULL, data STRING NOT NULL)" + " WITH ('connector'='BoundedSource', 'data-id'='%s')", SOURCE_TABLE, dataId);
    Assert.assertEquals("Should have the expected rows in source table.", Sets.newHashSet(dataSet), Sets.newHashSet(sql("SELECT * FROM %s", SOURCE_TABLE)));
    sql("CREATE TABLE %s(id INT, data VARCHAR) PARTITIONED BY (data) WITH %s", tableName, toWithClause(tableProps));
    try {
        // Insert data set.
        sql("INSERT INTO %s SELECT * FROM %s", tableName, SOURCE_TABLE);
        Assert.assertEquals("Should have the expected rows in sink table.", Sets.newHashSet(dataSet), Sets.newHashSet(sql("SELECT * FROM %s", tableName)));
        // Sometimes we will have more than one checkpoint if we pass the auto checkpoint interval,
        // thus producing multiple snapshots.  Here we assert that each snapshot has only 1 file per partition.
        Table table = validationCatalog.loadTable(TableIdentifier.of(icebergNamespace, tableName));
        Map<Long, List<DataFile>> snapshotToDataFiles = SimpleDataUtil.snapshotToDataFiles(table);
        for (List<DataFile> dataFiles : snapshotToDataFiles.values()) {
            if (dataFiles.isEmpty()) {
                continue;
            }
            Assert.assertEquals("There should be 1 data file in partition 'aaa'", 1, SimpleDataUtil.matchingPartitions(dataFiles, table.spec(), ImmutableMap.of("data", "aaa")).size());
            Assert.assertEquals("There should be 1 data file in partition 'bbb'", 1, SimpleDataUtil.matchingPartitions(dataFiles, table.spec(), ImmutableMap.of("data", "bbb")).size());
            Assert.assertEquals("There should be 1 data file in partition 'ccc'", 1, SimpleDataUtil.matchingPartitions(dataFiles, table.spec(), ImmutableMap.of("data", "ccc")).size());
        }
    } finally {
        sql("DROP TABLE IF EXISTS %s.%s", flinkDatabase, tableName);
    }
}

@Test
public void testLimitPushDown() {
    String querySql = String.format("SELECT * FROM %s LIMIT 1", TABLE_NAME);
    String explain = getTableEnv().explainSql(querySql);
    String expectedExplain = "limit=[1]";
    Assert.assertTrue("Explain should contain LimitPushDown", explain.contains(expectedExplain));
    List<Row> result = sql(querySql);
