/**
 * NaN is not supported by flink now, so we add the test case to assert the parse error, when we upgrade the flink
 * that supports NaN, we will delele the method, and add some test case to test NaN.
 */
@Test
public void testSqlParseError() {
    String sqlParseErrorEqual = String.format("SELECT * FROM %s WHERE d = CAST('NaN' AS DOUBLE) ", TABLE_NAME);
    AssertHelpers.assertThrows("The NaN is not supported by flink now. ", NumberFormatException.class, () -> sql(sqlParseErrorEqual));
    String sqlParseErrorNotEqual = String.format("SELECT * FROM %s WHERE d <> CAST('NaN' AS DOUBLE) ", TABLE_NAME);
    AssertHelpers.assertThrows("The NaN is not supported by flink now. ", NumberFormatException.class, () -> sql(sqlParseErrorNotEqual));
    String sqlParseErrorGT = String.format("SELECT * FROM %s WHERE d > CAST('NaN' AS DOUBLE) ", TABLE_NAME);
    AssertHelpers.assertThrows("The NaN is not supported by flink now. ", NumberFormatException.class, () -> sql(sqlParseErrorGT));
    String sqlParseErrorLT = String.format("SELECT * FROM %s WHERE d < CAST('NaN' AS DOUBLE) ", TABLE_NAME);
    AssertHelpers.assertThrows("The NaN is not supported by flink now. ", NumberFormatException.class, () -> sql(sqlParseErrorLT));
    String sqlParseErrorGTE = String.format("SELECT * FROM %s WHERE d >= CAST('NaN' AS DOUBLE) ", TABLE_NAME);
    AssertHelpers.assertThrows("The NaN is not supported by flink now. ", NumberFormatException.class, () -> sql(sqlParseErrorGTE));
    String sqlParseErrorLTE = String.format("SELECT * FROM %s WHERE d <= CAST('NaN' AS DOUBLE) ", TABLE_NAME);
    AssertHelpers.assertThrows("The NaN is not supported by flink now. ", NumberFormatException.class, () -> sql(sqlParseErrorLTE));
}

@Test
public void testUpsertAndQuery() {
    String tableName = "test_upsert_query";
    LocalDate dt20220301 = LocalDate.of(2022, 3, 1);
    LocalDate dt20220302 = LocalDate.of(2022, 3, 2);
    sql("CREATE TABLE %s(id INT NOT NULL, province STRING NOT NULL, dt DATE, PRIMARY KEY(id,province) NOT ENFORCED) " + "PARTITIONED BY (province) WITH %s", tableName, toWithClause(tableUpsertProps));
    try {
        sql("INSERT INTO %s VALUES " + "(1, 'a', DATE '2022-03-01')," + "(2, 'b', DATE '2022-03-01')," + "(1, 'b', DATE '2022-03-01')", tableName);
        sql("INSERT INTO %s VALUES " + "(4, 'a', DATE '2022-03-02')," + "(5, 'b', DATE '2022-03-02')," + "(1, 'b', DATE '2022-03-02')", tableName);
        List<Row> rowsOn20220301 = Lists.newArrayList(Row.of(2, "b", dt20220301), Row.of(1, "a", dt20220301));
        TestHelpers.assertRows(sql("SELECT * FROM %s WHERE dt < '2022-03-02'", tableName), rowsOn20220301);
        List<Row> rowsOn20220302 = Lists.newArrayList(Row.of(1, "b", dt20220302), Row.of(4, "a", dt20220302), Row.of(5, "b", dt20220302));
        TestHelpers.assertRows(sql("SELECT * FROM %s WHERE dt = '2022-03-02'", tableName), rowsOn20220302);
        TestHelpers.assertRows(sql("SELECT * FROM %s", tableName), Lists.newArrayList(Iterables.concat(rowsOn20220301, rowsOn20220302)));
    } finally {
        sql("DROP TABLE IF EXISTS %s.%s", flinkDatabase, tableName);
    }
}

@Test
public void testPrimaryKeyEqualToPartitionKey() {
    // This is an SQL based reproduction of TestFlinkIcebergSinkV2#testUpsertOnDataKey
    String tableName = "upsert_on_data_key";
    try {
        sql("CREATE TABLE %s(id INT NOT NULL, data STRING NOT NULL, PRIMARY KEY(data) NOT ENFORCED) " + "PARTITIONED BY (data) WITH %s", tableName, toWithClause(tableUpsertProps));
        sql("INSERT INTO %s VALUES " + "(1, 'aaa')," + "(2, 'aaa')," + "(3, 'bbb')", tableName);
        TestHelpers.assertRows(sql("SELECT * FROM %s", tableName), Lists.newArrayList(Row.of(2, "aaa"), Row.of(3, "bbb")));
        sql("INSERT INTO %s VALUES " + "(4, 'aaa')," + "(5, 'bbb')", tableName);
        TestHelpers.assertRows(sql("SELECT * FROM %s", tableName), Lists.newArrayList(Row.of(4, "aaa"), Row.of(5, "bbb")));
        sql("INSERT INTO %s VALUES " + "(6, 'aaa')," + "(7, 'bbb')", tableName);
        TestHelpers.assertRows(sql("SELECT * FROM %s", tableName), Lists.newArrayList(Row.of(6, "aaa"), Row.of(7, "bbb")));
    } finally {
        sql("DROP TABLE IF EXISTS %s.%s", flinkDatabase, tableName);
    }
}

