    Assert.assertEquals(1, result.dataFiles().length);
    Assert.assertEquals(1, result.deleteFiles().length);
    Assert.assertEquals(Sets.newHashSet(FileContent.POSITION_DELETES), Sets.newHashSet(result.deleteFiles()[0].content()));
    commitTransaction(result);
    Assert.assertEquals("Should have expected records", expectedRowSet(createRecord(1, "aaa")), actualRowSet("*"));
}

