            Assertions.assertThat(obj).as("Should be a position DeleteFile").isInstanceOf(DeleteFile.class);
            TestHelpers.assertEquals(POS_DELETE_FILE, (DeleteFile) obj);
        }
        for (int i = 0; i < 2; i += 1) {
