@Test
public void testAnd() {
    Expression expr = resolve(Expressions.$("field1").isEqual(Expressions.lit(1)).and(Expressions.$("field2").isEqual(Expressions.lit(2L))));
    Optional<org.apache.iceberg.expressions.Expression> actual = FlinkFilters.convert(expr);
    Assert.assertTrue("Conversion should succeed", actual.isPresent());
    And and = (And) actual.get();
    And expected = (And) org.apache.iceberg.expressions.Expressions.and(org.apache.iceberg.expressions.Expressions.equal("field1", 1), org.apache.iceberg.expressions.Expressions.equal("field2", 2L));
    assertPredicatesMatch(expected.left(), and.left());
