@Test
public void testEqualityDeleteWriter() throws IOException {
    File deleteFile = temp.newFile();
    OutputFile out = Files.localOutput(deleteFile);
    EqualityDeleteWriter<Record> deleteWriter = ORC.writeDeletes(out).createWriterFunc(GenericOrcWriter::buildWriter).overwrite().rowSchema(SCHEMA).withSpec(PartitionSpec.unpartitioned()).equalityFieldIds(1).buildEqualityWriter();
    try (EqualityDeleteWriter<Record> writer = deleteWriter) {
        writer.deleteAll(records);
    }
