    MessageType expected = Types.buildMessage().addField(Types.buildGroup(Type.Repetition.OPTIONAL).addField(Types.buildGroup(Type.Repetition.REPEATED).addField(Types.buildGroup(Type.Repetition.OPTIONAL).addField(Types.primitive(PrimitiveTypeName.DOUBLE, Type.Repetition.REQUIRED).id(4).named("x")).addField(Types.primitive(PrimitiveTypeName.DOUBLE, Type.Repetition.REQUIRED).id(5).named("y")).id(3).named("custom_element_name")).named("custom_repeated_name")).as(LogicalTypeAnnotation.listType()).id(1).named("m")).named("table");
    MessageType actual = ParquetSchemaUtil.pruneColumns(fileSchema, projection);
    Assert.assertEquals("Pruned schema should not rename repeated struct", expected, actual);
}

