    projectedP2 = points.get(1);
    Assert.assertNull("Should not project x", projectedP2.getField("x"));
    Assert.assertNull("Should project null y", projectedP2.getField("y"));
    Schema yRenamed = new Schema(Types.NestedField.optional(22, "points", Types.ListType.ofOptional(21, Types.StructType.of(Types.NestedField.optional(18, "z", Types.IntegerType.get())))));
