    List<GenericData.Record> expected = Lists.newArrayList(builder.set("made_current_at", firstSnapshotTimestamp * 1000).set("snapshot_id", firstSnapshotId).set("parent_id", null).set("is_current_ancestor", true).build(), builder.set("made_current_at", secondSnapshotTimestamp * 1000).set("snapshot_id", secondSnapshotId).set("parent_id", firstSnapshotId).set("is_current_ancestor", // commit rolled back, not an ancestor of the current table state
    false).build(), builder.set("made_current_at", rollbackTimestamp * 1000).set("snapshot_id", firstSnapshotId).set("parent_id", null).set("is_current_ancestor", true).build(), builder.set("made_current_at", thirdSnapshotTimestamp * 1000).set("snapshot_id", thirdSnapshotId).set("parent_id", firstSnapshotId).set("is_current_ancestor", true).build());
    Assert.assertEquals("History table should have a row for each commit", 4, actual.size());
    TestHelpers.assertEqualsSafe(historyTable.schema().asStruct(), expected.get(0), actual.get(0));
    TestHelpers.assertEqualsSafe(historyTable.schema().asStruct(), expected.get(1), actual.get(1));
    TestHelpers.assertEqualsSafe(historyTable.schema().asStruct(), expected.get(2), actual.get(2));
}

