@Test
@SuppressWarnings("unchecked")
public void testListOfStructsProjection() throws IOException {
    Schema writeSchema = new Schema(Types.NestedField.required(0, "id", Types.LongType.get()), Types.NestedField.optional(22, "points", Types.ListType.ofOptional(21, Types.StructType.of(Types.NestedField.required(19, "x", Types.IntegerType.get()), Types.NestedField.optional(18, "y", Types.IntegerType.get())))));
    Record record = GenericRecord.create(writeSchema);
    record.setField("id", 34L);
    Record p1 = GenericRecord.create(writeSchema.findType("points.element").asStructType());
    p1.setField("x", 1);
    p1.setField("y", 2);
    Record p2 = GenericRecord.create(p1.struct());
    p2.setField("x", 3);
    p2.setField("y", null);
    record.setField("points", ImmutableList.of(p1, p2));
    Schema idOnly = new Schema(Types.NestedField.required(0, "id", Types.LongType.get()));
    Record projected = writeAndRead("id_only", writeSchema, idOnly, record);
    Assert.assertEquals("Should contain the correct id value", 34L, (long) projected.getField("id"));
    Assert.assertNull("Should not project points list", projected.getField("points"));
    projected = writeAndRead("all_points", writeSchema, writeSchema.select("points"), record);
    Assert.assertNull("Should not project id", projected.getField("id"));
    Assert.assertEquals("Should project points list", record.getField("points"), projected.getField("points"));
    projected = writeAndRead("x_only", writeSchema, writeSchema.select("points.x"), record);
    Assert.assertNull("Should not project id", projected.getField("id"));
    Assert.assertNotNull("Should project points list", projected.getField("points"));
    List<Record> points = (List<Record>) projected.getField("points");
    Assert.assertEquals("Should read 2 points", 2, points.size());
    Record projectedP1 = points.get(0);
    Assert.assertEquals("Should project x", 1, (int) projectedP1.getField("x"));
    Assert.assertNull("Should not project y", projectedP1.getField("y"));
    Record projectedP2 = points.get(1);
    Assert.assertEquals("Should project x", 3, (int) projectedP2.getField("x"));
    Assert.assertNull("Should not project y", projectedP2.getField("y"));
    projected = writeAndRead("y_only", writeSchema, writeSchema.select("points.y"), record);
    Assert.assertNull("Should not project id", projected.getField("id"));
    Assert.assertNotNull("Should project points list", projected.getField("points"));
    points = (List<Record>) projected.getField("points");
    Assert.assertEquals("Should read 2 points", 2, points.size());
    projectedP1 = points.get(0);
    Assert.assertNull("Should not project x", projectedP1.getField("x"));
    Assert.assertEquals("Should project y", 2, (int) projectedP1.getField("y"));
    projectedP2 = points.get(1);
    Assert.assertNull("Should not project x", projectedP2.getField("x"));
    Assert.assertNull("Should project null y", projectedP2.getField("y"));
    Schema yRenamed = new Schema(Types.NestedField.optional(22, "points", Types.ListType.ofOptional(21, Types.StructType.of(Types.NestedField.optional(18, "z", Types.IntegerType.get())))));
    projected = writeAndRead("y_renamed", writeSchema, yRenamed, record);
    Assert.assertNull("Should not project id", projected.getField("id"));
    Assert.assertNotNull("Should project points list", projected.getField("points"));
    points = (List<Record>) projected.getField("points");
    Assert.assertEquals("Should read 2 points", 2, points.size());
    projectedP1 = points.get(0);
    Assert.assertNull("Should not project x", projectedP1.getField("x"));
    Assert.assertNull("Should not project y", projectedP1.getField("y"));
    Assert.assertEquals("Should project z", 2, (int) projectedP1.getField("z"));
    projectedP2 = points.get(1);
    Assert.assertNull("Should not project x", projectedP2.getField("x"));
    Assert.assertNull("Should not project y", projectedP2.getField("y"));
    Assert.assertNull("Should project null z", projectedP2.getField("z"));
    Schema zAdded = new Schema(Types.NestedField.optional(22, "points", Types.ListType.ofOptional(21, Types.StructType.of(Types.NestedField.required(19, "x", Types.IntegerType.get()), Types.NestedField.optional(18, "y", Types.IntegerType.get()), Types.NestedField.optional(20, "z", Types.IntegerType.get())))));
    projected = writeAndRead("z_added", writeSchema, zAdded, record);
    Assert.assertNull("Should not project id", projected.getField("id"));
    Assert.assertNotNull("Should project points list", projected.getField("points"));
    points = (List<Record>) projected.getField("points");
    Assert.assertEquals("Should read 2 points", 2, points.size());
    projectedP1 = points.get(0);
    Assert.assertEquals("Should project x", 1, (int) projectedP1.getField("x"));
    Assert.assertEquals("Should project y", 2, (int) projectedP1.getField("y"));
    Assert.assertNull("Should contain null z", projectedP1.getField("z"));
    projectedP2 = points.get(1);
    Assert.assertEquals("Should project x", 3, (int) projectedP2.getField("x"));
    Assert.assertNull("Should project null y", projectedP2.getField("y"));
    Assert.assertNull("Should contain null z", projectedP2.getField("z"));
}

@Test
public void testSnapshotSelectionById() throws IOException {
    String tableLocation = temp.newFolder("iceberg-table").toString();
    HadoopTables tables = new HadoopTables(CONF);
    PartitionSpec spec = PartitionSpec.unpartitioned();
    Table table = tables.create(SCHEMA, spec, tableLocation);
    // produce the first snapshot
    List<SimpleRecord> firstBatchRecords = Lists.newArrayList(new SimpleRecord(1, "a"), new SimpleRecord(2, "b"), new SimpleRecord(3, "c"));
    Dataset<Row> firstDf = spark.createDataFrame(firstBatchRecords, SimpleRecord.class);
    firstDf.select("id", "data").write().format("iceberg").mode("append").save(tableLocation);
    // produce the second snapshot
    List<SimpleRecord> secondBatchRecords = Lists.newArrayList(new SimpleRecord(4, "d"), new SimpleRecord(5, "e"), new SimpleRecord(6, "f"));
    Dataset<Row> secondDf = spark.createDataFrame(secondBatchRecords, SimpleRecord.class);
    secondDf.select("id", "data").write().format("iceberg").mode("append").save(tableLocation);
    Assert.assertEquals("Expected 2 snapshots", 2, Iterables.size(table.snapshots()));
    // verify records in the current snapshot
    Dataset<Row> currentSnapshotResult = spark.read().format("iceberg").load(tableLocation);
    List<SimpleRecord> currentSnapshotRecords = currentSnapshotResult.orderBy("id").as(Encoders.bean(SimpleRecord.class)).collectAsList();
    List<SimpleRecord> expectedRecords = Lists.newArrayList();
    expectedRecords.addAll(firstBatchRecords);
    expectedRecords.addAll(secondBatchRecords);
    Assert.assertEquals("Current snapshot rows should match", expectedRecords, currentSnapshotRecords);
    // verify records in the previous snapshot
    Snapshot currentSnapshot = table.currentSnapshot();
    Long parentSnapshotId = currentSnapshot.parentId();
    Dataset<Row> previousSnapshotResult = spark.read().format("iceberg").option("snapshot-id", parentSnapshotId).load(tableLocation);
    List<SimpleRecord> previousSnapshotRecords = previousSnapshotResult.orderBy("id").as(Encoders.bean(SimpleRecord.class)).collectAsList();
    Assert.assertEquals("Previous snapshot rows should match", firstBatchRecords, previousSnapshotRecords);
}

