@Test
public void testClosureOnDataExhaustion() throws IOException {
    Integer totalTasks = 10;
    Integer recordPerTask = 10;
    List<FileScanTask> tasks = createFileScanTasks(totalTasks, recordPerTask);
    ClosureTrackingReader reader = new ClosureTrackingReader(table, tasks);
    int countRecords = 0;
    while (reader.next()) {
        countRecords += 1;
        Assert.assertNotNull("Reader should return non-null value", reader.get());
    }
    Assert.assertEquals("Reader returned incorrect number of records", totalTasks * recordPerTask, countRecords);
    tasks.forEach(t -> Assert.assertTrue("All iterators should be closed after read exhausion", reader.isIteratorClosed(t)));
}

@Test
public void testClosureDuringIteration() throws IOException {
    Integer totalTasks = 2;
    Integer recordPerTask = 1;
    List<FileScanTask> tasks = createFileScanTasks(totalTasks, recordPerTask);
    Assert.assertEquals(2, tasks.size());
    FileScanTask firstTask = tasks.get(0);
    FileScanTask secondTask = tasks.get(1);
    ClosureTrackingReader reader = new ClosureTrackingReader(table, tasks);
    // Total of 2 elements
    Assert.assertTrue(reader.next());
    Assert.assertFalse("First iter should not be closed on its last element", reader.isIteratorClosed(firstTask));
    Assert.assertTrue(reader.next());
    Assert.assertTrue("First iter should be closed after moving to second iter", reader.isIteratorClosed(firstTask));
    Assert.assertFalse("Second iter should not be closed on its last element", reader.isIteratorClosed(secondTask));
    Assert.assertFalse(reader.next());
    Assert.assertTrue(reader.isIteratorClosed(firstTask));
    Assert.assertTrue(reader.isIteratorClosed(secondTask));
}

