    List<SimpleRecord> actual = rowsAvailable(query);
    Assertions.assertThat(actual.isEmpty()).isTrue();
    List<SimpleRecord> data = Lists.newArrayList(new SimpleRecord(-2, "minustwo"), new SimpleRecord(-1, "minusone"), new SimpleRecord(0, "zero"));
