    Expression localDateExpression = SparkFilters.convert(GreaterThan.apply("x", localDate));
    Expression dateExpression = SparkFilters.convert(GreaterThan.apply("x", date));
    Expression rawExpression = Expressions.greaterThan("x", epochDay);
    Assert.assertEquals("Generated localdate expression should be correct", rawExpression.toString(), localDateExpression.toString());
    Assert.assertEquals("Generated date expression should be correct", rawExpression.toString(), dateExpression.toString());
}

