    createPartitionedHiveTable();
    String createIceberg = "CREATE TABLE %s (id Integer, name String, dept String, subdept String) USING iceberg PARTITIONED BY (id)";
    sql(createIceberg, tableName);
    scalarSql("CALL %s.system.add_files(" + "table => '%s', " + "source_table => '%s', " + "partition_filter => map('id', 1))", catalogName, tableName, sourceTableName);
    AssertHelpers.assertThrows("Should not allow adding duplicate files", IllegalStateException.class, "Cannot complete import because data files to be imported already" + " exist within the target table", () -> scalarSql("CALL %s.system.add_files(" + "table => '%s', " + "source_table => '%s', " + "partition_filter => map('id', 1))", catalogName, tableName, sourceTableName));
}

@Test
public void duplicateDataPartitionedAllowed() {
    createPartitionedHiveTable();
    String createIceberg = "CREATE TABLE %s (id Integer, name String, dept String, subdept String) USING iceberg PARTITIONED BY (id)";
    sql(createIceberg, tableName);
    Object result1 = scalarSql("CALL %s.system.add_files(" + "table => '%s', " + "source_table => '%s', " + "partition_filter => map('id', 1))", catalogName, tableName, sourceTableName);
    Assert.assertEquals(2L, result1);
    Object result2 = scalarSql("CALL %s.system.add_files(" + "table => '%s', " + "source_table => '%s', " + "partition_filter => map('id', 1)," + "check_duplicate_files => false)", catalogName, tableName, sourceTableName);
    Assert.assertEquals(2L, result2);
    assertEquals("Iceberg table contains correct data", sql("SELECT id, name, dept, subdept FROM %s WHERE id = 1 UNION ALL " + "SELECT id, name, dept, subdept FROM %s WHERE id = 1", sourceTableName, sourceTableName), sql("SELECT id, name, dept, subdept FROM %s", tableName, tableName));
}

