@Test
public void addOrcFileWithDoubleAndFloatColumns() throws Exception {
    // Spark Session Catalog cannot load metadata tables
    // with "The namespace in session catalog must have exactly one name part"
    Assume.assumeFalse(catalogName.equals("spark_catalog"));
    // Create an ORC file
    File outputFile = temp.newFile("test.orc");
    final int numRows = 5;
    List<Record> expectedRecords = createOrcFile(outputFile, numRows);
    String createIceberg = "CREATE TABLE %s (x float, y double, z long) USING iceberg";
    sql(createIceberg, tableName);
    Object result = scalarSql("CALL %s.system.add_files('%s', '`orc`.`%s`')", catalogName, tableName, outputFile.getPath());
    Assert.assertEquals(1L, result);
    List<Object[]> expected = expectedRecords.stream().map(record -> new Object[] { record.get(0), record.get(1), record.get(2) }).collect(Collectors.toList());
    // x goes 2.00, 1.99, 1.98, ...
    assertEquals("Iceberg table contains correct data", expected, sql("SELECT * FROM %s ORDER BY x DESC", tableName));
    List<Object[]> actualRecordCount = sql("select %s from %s.files", DataFile.RECORD_COUNT.name(), tableName);
    List<Object[]> expectedRecordCount = Lists.newArrayList();
    expectedRecordCount.add(new Object[] { (long) numRows });
    assertEquals("Iceberg file metadata should have correct metadata count", expectedRecordCount, actualRecordCount);
}

