    assertEquals("Should have expected rows", ImmutableList.of(row(-1, "hr"), row(1, "hr")), sql("SELECT * FROM %s ORDER BY id", tableName));
    append(new Employee(null, "hr"), new Employee(2, "hr"));
    assertEquals("Should have expected rows", ImmutableList.of(row(-1, "hr"), row(1, "hr"), row(2, "hr"), row(null, "hr")), sql("SELECT * FROM %s ORDER BY id ASC NULLS LAST", tableName));
    sql("DELETE FROM %s WHERE id IN (SELECT value + 2 FROM deleted_id) AND dep = 'hr'", tableName);
    assertEquals("Should have expected rows", ImmutableList.of(row(-1, "hr"), row(1, "hr"), row(null, "hr")), sql("SELECT * FROM %s ORDER BY id ASC NULLS LAST", tableName));
}

