@Test
public void testInvalidSnapshotsCases() throws IOException {
    String location = temp.newFolder().toString();
    sql("CREATE TABLE %s (id bigint NOT NULL, data string) USING parquet LOCATION '%s'", sourceName, location);
    AssertHelpers.assertThrows("Should reject calls without all required args", AnalysisException.class, "Missing required parameters", () -> sql("CALL %s.system.snapshot('foo')", catalogName));
    AssertHelpers.assertThrows("Should reject calls with invalid arg types", AnalysisException.class, "Wrong arg type", () -> sql("CALL %s.system.snapshot('n', 't', map('foo', 'bar'))", catalogName));
    AssertHelpers.assertThrows("Should reject calls with invalid map args", AnalysisException.class, "cannot resolve 'map", () -> sql("CALL %s.system.snapshot('%s', 'fable', 'loc', map(2, 1, 1))", catalogName, sourceName));
    AssertHelpers.assertThrows("Should reject calls with empty table identifier", IllegalArgumentException.class, "Cannot handle an empty identifier", () -> sql("CALL %s.system.snapshot('', 'dest')", catalogName));
    AssertHelpers.assertThrows("Should reject calls with empty table identifier", IllegalArgumentException.class, "Cannot handle an empty identifier", () -> sql("CALL %s.system.snapshot('src', '')", catalogName));
}

