    sql("DROP TABLE IF EXISTS %s", tableName("third"));
    sql("CREATE TABLE %s (\n" + "    id bigint COMMENT 'unique id',\n" + "    data string)\n" + "USING iceberg", tableName("first"));
    // Table should exist
    getTable("first");
