    List<Row> updatedRecords = Lists.newArrayList(RowFactory.create(1, "x", null), RowFactory.create(2, "y", null), RowFactory.create(3, "z", null), RowFactory.create(4, "xy", "B"), RowFactory.create(5, "xyz", "C"));
