@Test
public void testProjections() {
    String[][] cases = new String[][] { // individual fields
    new String[] { "date" }, new String[] { "level" }, new String[] { "message" }, // field pairs
    new String[] { "date", "message" }, new String[] { "level", "message" }, new String[] { "date", "level" }, // out-of-order pairs
    new String[] { "message", "date" }, new String[] { "message", "level" }, new String[] { "level", "date" }, // full projection, different orderings
    new String[] { "date", "level", "message" }, new String[] { "level", "date", "message" }, new String[] { "date", "message", "level" }, new String[] { "level", "message", "date" }, new String[] { "message", "date", "level" }, new String[] { "message", "level", "date" } };
    for (String[] ordering : cases) {
        List<Row> expected = logs.select("id", ordering).orderBy("id").collectAsList();
        List<Row> actual = spark.read().format("iceberg").option(SparkReadOptions.VECTORIZATION_ENABLED, String.valueOf(vectorized)).load(table.location()).select("id", ordering).orderBy("id").collectAsList();
        Assert.assertEquals("Rows should match for ordering: " + Arrays.toString(ordering), expected, actual);
    }
}

