    Configuration configFromJavaSerde = ((Configurable) javaSerializedTable.io()).getConf();
    String javaSerializedCatalogOverride = configFromJavaSerde.get(configToOverride, "/whammies");
    Assert.assertEquals("Tables serialized with Java serialization should retain overridden hadoop configuration properties", configOverrideValue, javaSerializedCatalogOverride);
}

