@Test
public void addTwice() {
    createPartitionedHiveTable();
    String createIceberg = "CREATE TABLE %s (id Integer, name String, dept String, subdept String) USING iceberg PARTITIONED BY (id)";
    sql(createIceberg, tableName);
    Object result1 = scalarSql("CALL %s.system.add_files(" + "table => '%s', " + "source_table => '%s', " + "partition_filter => map('id', 1))", catalogName, tableName, sourceTableName);
    Assert.assertEquals(2L, result1);
    Object result2 = scalarSql("CALL %s.system.add_files(" + "table => '%s', " + "source_table => '%s', " + "partition_filter => map('id', 2))", catalogName, tableName, sourceTableName);
    Assert.assertEquals(2L, result2);
    assertEquals("Iceberg table contains correct data", sql("SELECT id, name, dept, subdept FROM %s WHERE id = 1 ORDER BY id", sourceTableName), sql("SELECT id, name, dept, subdept FROM %s WHERE id = 1 ORDER BY id", tableName));
    assertEquals("Iceberg table contains correct data", sql("SELECT id, name, dept, subdept FROM %s WHERE id = 2 ORDER BY id", sourceTableName), sql("SELECT id, name, dept, subdept FROM %s WHERE id = 2 ORDER BY id", tableName));
}

