    Object pathResult = scalarSql("CALL %s.system.add_files('%s', '`parquet`.`%s`')", catalogName, tableName, fileTableDir.getAbsolutePath());
    Assert.assertEquals(0L, pathResult);
    assertEquals("Iceberg table contains no added data when importing from an empty path", emptyQueryResult, sql("SELECT * FROM %s ORDER BY id", tableName));
    // Empty table based import
    String createHive = "CREATE TABLE %s (id Integer, name String, dept String, subdept String) STORED AS parquet";
    sql(createHive, sourceTableName);
    Object tableResult = scalarSql("CALL %s.system.add_files('%s', '%s')", catalogName, tableName, sourceTableName);
    Assert.assertEquals(0L, tableResult);
    assertEquals("Iceberg table contains no added data when importing from an empty table", emptyQueryResult, sql("SELECT * FROM %s ORDER BY id", tableName));
}

