@Test
public void testRewriteDataFilesWithAllPossibleFilters() {
    createPartitionTable();
    // create 5 files for each partition (c2 = 'foo' and c2 = 'bar')
    insertData(10);
    // Pass the literal value which is not present in the data files.
    // So that parsing can be tested on a same dataset without actually compacting the files.
    // EqualTo
    sql("CALL %s.system.rewrite_data_files(table => '%s'," + " where => 'c1 = 3')", catalogName, tableIdent);
    // GreaterThan
    sql("CALL %s.system.rewrite_data_files(table => '%s'," + " where => 'c1 > 3')", catalogName, tableIdent);
    // GreaterThanOrEqual
    sql("CALL %s.system.rewrite_data_files(table => '%s'," + " where => 'c1 >= 3')", catalogName, tableIdent);
    // LessThan
    sql("CALL %s.system.rewrite_data_files(table => '%s'," + " where => 'c1 < 0')", catalogName, tableIdent);
    // LessThanOrEqual
    sql("CALL %s.system.rewrite_data_files(table => '%s'," + " where => 'c1 <= 0')", catalogName, tableIdent);
    // In
    sql("CALL %s.system.rewrite_data_files(table => '%s'," + " where => 'c1 in (3,4,5)')", catalogName, tableIdent);
    // IsNull
    sql("CALL %s.system.rewrite_data_files(table => '%s'," + " where => 'c1 is null')", catalogName, tableIdent);
    // IsNotNull
    sql("CALL %s.system.rewrite_data_files(table => '%s'," + " where => 'c3 is not null')", catalogName, tableIdent);
    // And
    sql("CALL %s.system.rewrite_data_files(table => '%s'," + " where => 'c1 = 3 and c2 = \"bar\"')", catalogName, tableIdent);
    // Or
    sql("CALL %s.system.rewrite_data_files(table => '%s'," + " where => 'c1 = 3 or c1 = 5')", catalogName, tableIdent);
    // Not
    sql("CALL %s.system.rewrite_data_files(table => '%s'," + " where => 'c1 not in (1,2)')", catalogName, tableIdent);
    // StringStartsWith
    sql("CALL %s.system.rewrite_data_files(table => '%s'," + " where => 'c2 like \"%s\"')", catalogName, tableIdent, "car%");
    // TODO: Enable when org.apache.iceberg.spark.SparkFilters have implementations for StringEndsWith & StringContains
    // StringEndsWith
    // sql("CALL %s.system.rewrite_data_files(table => '%s'," +
    //     " where => 'c2 like \"%s\"')", catalogName, tableIdent, "%car");
    // StringContains
    // sql("CALL %s.system.rewrite_data_files(table => '%s'," +
    //     " where => 'c2 like \"%s\"')", catalogName, tableIdent, "%car%");
}

