@Test
public void testRollbackToSnapshotUsingPositionalArgs() {
    sql("CREATE TABLE %s (id bigint NOT NULL, data string) USING iceberg", tableName);
    sql("INSERT INTO TABLE %s VALUES (1, 'a')", tableName);
    Table table = validationCatalog.loadTable(tableIdent);
    Snapshot firstSnapshot = table.currentSnapshot();
    sql("INSERT INTO TABLE %s VALUES (1, 'a')", tableName);
    assertEquals("Should have expected rows", ImmutableList.of(row(1L, "a"), row(1L, "a")), sql("SELECT * FROM %s ORDER BY id", tableName));
    table.refresh();
    Snapshot secondSnapshot = table.currentSnapshot();
    List<Object[]> output = sql("CALL %s.system.rollback_to_snapshot('%s', %dL)", catalogName, tableIdent, firstSnapshot.snapshotId());
    assertEquals("Procedure output must match", ImmutableList.of(row(secondSnapshot.snapshotId(), firstSnapshot.snapshotId())), output);
    assertEquals("Rollback must be successful", ImmutableList.of(row(1L, "a")), sql("SELECT * FROM %s ORDER BY id", tableName));
}

