@Test
public void testMergeSchemaFailsWithoutWriterOption() throws Exception {
    sql("ALTER TABLE %s SET TBLPROPERTIES ('%s'='true')", tableName, TableProperties.SPARK_WRITE_ACCEPT_ANY_SCHEMA);
    Dataset<Row> twoColDF = jsonToDF("id bigint, data string", "{ \"id\": 1, \"data\": \"a\" }", "{ \"id\": 2, \"data\": \"b\" }");
    twoColDF.writeTo(tableName).append();
    assertEquals("Should have initial 2-column rows", ImmutableList.of(row(1L, "a"), row(2L, "b")), sql("select * from %s order by id", tableName));
    Dataset<Row> threeColDF = jsonToDF("id bigint, data string, new_col float", "{ \"id\": 3, \"data\": \"c\", \"new_col\": 12.06 }", "{ \"id\": 4, \"data\": \"d\", \"new_col\": 14.41 }");
    // this has a different error message than the case without accept-any-schema because it uses Iceberg checks
    AssertHelpers.assertThrows("Should fail when merge-schema is not enabled on the writer", IllegalArgumentException.class, "Field new_col not found in source schema", () -> {
        try {
            threeColDF.writeTo(tableName).append();
        } catch (NoSuchTableException e) {
            // needed because append has checked exceptions
            throw new RuntimeException(e);
        }
    });
}

