    df1.select("id", "data").write().format("iceberg").mode("append").save(loadLocation(tableIdentifier));
    table.refresh();
    long firstCommitId = table.currentSnapshot().snapshotId();
    // add a second file
    df2.select("id", "data").write().format("iceberg").mode("append").save(loadLocation(tableIdentifier));
    List<Row> actual = spark.read().format("iceberg").load(loadLocation(tableIdentifier, "partitions")).orderBy("partition.id").collectAsList();
    GenericRecordBuilder builder = new GenericRecordBuilder(AvroSchemaUtil.convert(partitionsTable.schema(), "partitions"));
    GenericRecordBuilder partitionBuilder = new GenericRecordBuilder(AvroSchemaUtil.convert(partitionsTable.schema().findType("partition").asStructType(), "partition"));
    List<GenericData.Record> expected = Lists.newArrayList();
    expected.add(builder.set("partition", partitionBuilder.set("id", 1).build()).set("record_count", 1L).set("file_count", 1).set("spec_id", 0).build());
    expected.add(builder.set("partition", partitionBuilder.set("id", 2).build()).set("record_count", 1L).set("file_count", 1).set("spec_id", 0).build());
    Assert.assertEquals("Partitions table should have two rows", 2, expected.size());
    Assert.assertEquals("Actual results should have two rows", 2, actual.size());
    for (int i = 0; i < 2; i += 1) {
        TestHelpers.assertEqualsSafe(partitionsTable.schema().asStruct(), expected.get(i), actual.get(i));
    }
    // check time travel
    List<Row> actualAfterFirstCommit = spark.read().format("iceberg").option(SparkReadOptions.SNAPSHOT_ID, String.valueOf(firstCommitId)).load(loadLocation(tableIdentifier, "partitions")).orderBy("partition.id").collectAsList();
    Assert.assertEquals("Actual results should have one row", 1, actualAfterFirstCommit.size());
    TestHelpers.assertEqualsSafe(partitionsTable.schema().asStruct(), expected.get(0), actualAfterFirstCommit.get(0));
    // check predicate push down
    List<Row> filtered = spark.read().format("iceberg").load(loadLocation(tableIdentifier, "partitions")).filter("partition.id < 2").collectAsList();
    Assert.assertEquals("Actual results should have one row", 1, filtered.size());
    TestHelpers.assertEqualsSafe(partitionsTable.schema().asStruct(), expected.get(0), filtered.get(0));
    List<Row> nonFiltered = spark.read().format("iceberg").load(loadLocation(tableIdentifier, "partitions")).filter("partition.id < 2 or record_count=1").collectAsList();
    Assert.assertEquals("Actual results should have one row", 2, nonFiltered.size());
    for (int i = 0; i < 2; i += 1) {
        TestHelpers.assertEqualsSafe(partitionsTable.schema().asStruct(), expected.get(i), actual.get(i));
    }
}

