    tables.create(SCHEMA, spec, location.toString());
    MemoryStream<Integer> inputStream = newMemoryStream(1, spark.sqlContext(), Encoders.INT());
    DataStreamWriter<Row> streamWriter = inputStream.toDF().selectExpr("value AS id", "CAST (value AS STRING) AS data").writeStream().outputMode("update").format("iceberg").option("checkpointLocation", checkpoint.toString()).option("path", location.toString());
    try {
        StreamingQuery query = streamWriter.start();
        List<Integer> batch1 = Lists.newArrayList(1, 2);
        send(batch1, inputStream);
        query.processAllAvailable();
    } finally {
        for (StreamingQuery query : spark.streams().active()) {
            query.stop();
        }
    }
}

