    Types.StructType expectedSchema = Types.StructType.of(NestedField.required(1, "id", Types.LongType.get()), NestedField.optional(2, "data", Types.StringType.get()), NestedField.optional(3, "data2", Types.MapType.ofOptional(4, 5, Types.StructType.of(NestedField.optional(6, "x", Types.IntegerType.get())), Types.StructType.of(NestedField.optional(7, "a", Types.IntegerType.get()), NestedField.optional(8, "b", Types.IntegerType.get()), NestedField.optional(9, "c", Types.IntegerType.get())))));
    Assert.assertEquals("Schema should match expected", expectedSchema, validationCatalog.loadTable(tableIdent).schema().asStruct());
    // should not allow changing map key column
    AssertHelpers.assertThrows("Should reject changing key of the map column", SparkException.class, "Unsupported table change: Cannot add fields to map keys:", () -> sql("ALTER TABLE %s ADD COLUMN data2.key.y int", tableName));
}

