@Test
public void testMergeWithMultipleUpdatesForTargetRowSmallTargetLargeSource() {
    createAndInitTable("id INT, dep STRING", "{ \"id\": 1, \"dep\": \"emp-id-one\" }\n" + "{ \"id\": 6, \"dep\": \"emp-id-6\" }");
    List<Integer> sourceIds = Lists.newArrayList();
    for (int i = 0; i < 10_000; i++) {
        sourceIds.add(i);
    }
    Dataset<Integer> ds = spark.createDataset(sourceIds, Encoders.INT());
    ds.union(ds).createOrReplaceTempView("source");
    String errorMsg = "a single row from the target table with multiple rows of the source table";
    AssertHelpers.assertThrowsCause("Should complain about multiple matches", SparkException.class, errorMsg, () -> {
        sql("MERGE INTO %s AS t USING source AS s " + "ON t.id == s.value " + "WHEN MATCHED AND t.id = 1 THEN " + "  UPDATE SET id = 10 " + "WHEN MATCHED AND t.id = 6 THEN " + "  DELETE " + "WHEN NOT MATCHED AND s.value = 2 THEN " + "  INSERT (id, dep) VALUES (s.value, null)", tableName);
    });
    assertEquals("Target should be unchanged", ImmutableList.of(row(1, "emp-id-one"), row(6, "emp-id-6")), sql("SELECT * FROM %s ORDER BY id ASC NULLS LAST", tableName));
}

