        withSQLConf(ImmutableMap.of("spark.sql.storeAssignmentPolicy", policy), () -> {
            AssertHelpers.assertThrows("Should complain about writing nulls to a top-level column", AnalysisException.class, "Cannot write nullable values to non-null column", () -> sql("UPDATE %s t SET t.id = NULL", tableName));
            AssertHelpers.assertThrows("Should complain about writing nulls to a nested column", AnalysisException.class, "Cannot write nullable values to non-null column", () -> sql("UPDATE %s t SET t.s.n1 = NULL", tableName));
            AssertHelpers.assertThrows("Should complain about writing missing fields in structs", AnalysisException.class, "missing fields", () -> sql("UPDATE %s t SET t.s = named_struct('n1', 1)", tableName));
            AssertHelpers.assertThrows("Should complain about writing invalid data types", AnalysisException.class, "Cannot safely cast", () -> sql("UPDATE %s t SET t.s.n1 = 'str'", tableName));
            AssertHelpers.assertThrows("Should complain about writing incompatible structs", AnalysisException.class, "field name does not match", () -> sql("UPDATE %s t SET t.s.n2 = named_struct('dn2', 1, 'dn1', 2)", tableName));
        });
    }
}

